class NearuApp extends StatefulWidget {
  const NearuApp({super.key});

  @override
  State<NearuApp> createState() => _NearuAppState();
}

class _NearuAppState extends State<NearuApp> {
  final AppSettingsService _settingsService = AppSettingsService();
  AppSettings _settings = const AppSettings();
  Timer? _settingsTimer;

  @override
  void initState() {
    super.initState();
    _loadSettings();
  }

  @override
  void dispose() {
    _settingsTimer?.cancel();
    _settingsService.close();
    super.dispose();
  }

  Future<void> _loadSettings() async {
    try {
      final settings = await _settingsService.fetchSettings();
      if (!mounted) {
        return;
      }
      setState(() {
        _settings = settings;
      });
      _settingsTimer?.cancel();
      _settingsTimer = Timer(
        Duration(seconds: settings.updateIntervalSeconds),
        _loadSettings,
      );
    } catch (_) {
      _settingsTimer?.cancel();
      _settingsTimer = Timer(const Duration(seconds: 30), _loadSettings);
    }
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: _settings.siteName,
      theme: ThemeData(
        useMaterial3: true,
        scaffoldBackgroundColor: _settings.backgroundColor,
        colorScheme:
            ColorScheme.fromSeed(
              seedColor: _settings.accentColor,
              brightness: Brightness.light,
            ).copyWith(
              primary: _settings.primaryColor,
              secondary: _settings.secondaryColor,
              surface: _settings.surfaceColor,
            ),
        fontFamily: 'Segoe UI',
      ),
      home: const BncLaunchFlow(),
    );
  }
}

class BncLaunchFlow extends StatefulWidget {
  const BncLaunchFlow({super.key});

  @override
  State<BncLaunchFlow> createState() => _BncLaunchFlowState();
}

class _BncLaunchFlowState extends State<BncLaunchFlow> {
  bool _showHome = false;
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    _timer = Timer(const Duration(milliseconds: 2400), () {
      if (!mounted) {
        return;
      }

      setState(() {
        _showHome = true;
      });
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedSwitcher(
      duration: const Duration(milliseconds: 420),
      child: _showHome
          ? const NearuHomePage()
          : const BncSplashScreen(key: ValueKey('bnc-splash')),
    );
  }
}

class BncSplashScreen extends StatefulWidget {
  const BncSplashScreen({super.key});

  @override
  State<BncSplashScreen> createState() => _BncSplashScreenState();
}

class _BncSplashScreenState extends State<BncSplashScreen>
    with SingleTickerProviderStateMixin {
  late final AnimationController _streakController;
  Timer? _typingTimer;
  String _typedTitle = '';
  String _typedSubtitle = '';
  int _typingIndex = 0;

  static const String _fullTitle = 'BNC';
  static const String _fullSubtitle =
      'Launching your premium local marketplace';

  @override
  void initState() {
    super.initState();
    _streakController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1350),
    )..forward();
    _typingTimer = Timer.periodic(const Duration(milliseconds: 38), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }

      setState(() {
        if (_typingIndex < _fullTitle.length) {
          _typedTitle = _fullTitle.substring(0, _typingIndex + 1);
        } else {
          final subtitleIndex = _typingIndex - _fullTitle.length;
          if (subtitleIndex < _fullSubtitle.length) {
            _typedSubtitle = _fullSubtitle.substring(0, subtitleIndex + 1);
          } else {
            timer.cancel();
          }
        }
        _typingIndex += 1;
      });
    });
  }

  @override
  void dispose() {
    _typingTimer?.cancel();
    _streakController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        color: Colors.white,
        child: SafeArea(
          child: Center(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 28),
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Container(
                    width: 182,
                    height: 182,
                    decoration: BoxDecoration(
                      borderRadius: BorderRadius.circular(42),
                      border: Border.all(
                        color: brandNavy.withValues(alpha: 0.18),
                        width: 5,
                      ),
                      boxShadow: const [
                        BoxShadow(
                          color: Color(0x3301184A),
                          blurRadius: 34,
                          offset: Offset(0, 18),
                        ),
                      ],
                    ),
                    child: ClipRRect(
                      borderRadius: BorderRadius.circular(37),
                      child: Stack(
                        children: [
                          Positioned.fill(
                            child: Image.asset(
                              'assets/branding/bnc-logo.png',
                              fit: BoxFit.cover,
                              filterQuality: FilterQuality.high,
                            ),
                          ),
                          Positioned.fill(
                            child: AnimatedBuilder(
                              animation: _streakController,
                              builder: (context, _) {
                                return CustomPaint(
                                  painter: _BncLogoStreakPainter(
                                    progress: _streakController.value,
                                  ),
                                );
                              },
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                  const SizedBox(height: 24),
                  Text(
                    _typedTitle,
                    style: const TextStyle(
                      color: brandNavy,
                      fontSize: 32,
                      fontWeight: FontWeight.w900,
                      letterSpacing: 1.2,
                    ),
                  ),
                  const SizedBox(height: 10),
                  Text(
                    _typedSubtitle,
                    textAlign: TextAlign.center,
                    style: const TextStyle(
                      color: brandMuted,
                      fontSize: 15,
                      height: 1.45,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _BncLogoStreakPainter extends CustomPainter {
  const _BncLogoStreakPainter({required this.progress});

  final double progress;

  @override
  void paint(Canvas canvas, Size size) {
    final travel = Curves.easeInOutCubic.transform(progress);
    final pulse = 0.5 + (0.5 * math.sin(progress * math.pi * 2));
    final starCenter = Offset(size.width * 0.78, size.height * 0.24);
    final travelPath = Path()
      ..moveTo(size.width * 0.05, size.height * 0.50)
      ..cubicTo(
        size.width * 0.28,
        size.height * 0.28,
        size.width * 0.58,
        size.height * 0.18,
        size.width * 0.77,
        size.height * 0.24,
      );
    final metric = travelPath.computeMetrics().first;
    final lightPosition =
        metric.getTangentForOffset(metric.length * travel)?.position ??
        starCenter;
    final starArrival = travel > 0.78
        ? ((travel - 0.78) / 0.22).clamp(0.0, 1.0)
        : 0.0;

    canvas.saveLayer(Offset.zero & size, Paint());

    final movingGlow = Paint()
      ..shader = RadialGradient(
        colors: [
          Colors.white.withValues(alpha: 0.34),
          brandGold.withValues(alpha: 0.46),
          brandGold.withValues(alpha: 0.16),
          brandGold.withValues(alpha: 0),
        ],
        stops: const [0, 0.24, 0.55, 1],
      ).createShader(Rect.fromCircle(center: lightPosition, radius: 30))
      ..blendMode = BlendMode.plus;
    canvas.drawCircle(lightPosition, 30, movingGlow);

    final trailGlow = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 18
      ..strokeCap = StrokeCap.round
      ..color = brandGold.withValues(alpha: 0.05 + (pulse * 0.04))
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 18)
      ..blendMode = BlendMode.plus;
    canvas.drawPath(travelPath, trailGlow);

    final starGlow = Paint()
      ..shader =
          RadialGradient(
            colors: [
              Colors.white.withValues(alpha: 0.16 + (starArrival * 0.42)),
              brandGold.withValues(alpha: 0.20 + (starArrival * 0.38)),
              brandGold.withValues(alpha: 0),
            ],
            stops: const [0, 0.34, 1],
          ).createShader(
            Rect.fromCircle(
              center: starCenter,
              radius: 30 + (starArrival * 22),
            ),
          )
      ..blendMode = BlendMode.plus;
    canvas.drawCircle(starCenter, 30 + (starArrival * 22), starGlow);

    canvas.restore();
  }

  @override
  bool shouldRepaint(_BncLogoStreakPainter oldDelegate) {
    return oldDelegate.progress != progress;
  }
}

class NearuHomePage extends StatefulWidget {
  const NearuHomePage({super.key, this.catalogService});

  final CatalogService? catalogService;

  @override
  State<NearuHomePage> createState() => _NearuHomePageState();
}

class _NearuHomePageState extends State<NearuHomePage> {
  late final CatalogService _catalogService;
  late final bool _ownsCatalogService;

  CatalogData _catalog = fallbackCatalog;
  CatalogQuery _activeQuery = const CatalogQuery();
  DetectedLocation? _detectedLocation;
  bool _isLoadingCatalog = true;
  bool _usingFallback = false;
  bool _isDetectingLocation = false;
  String? _catalogError;
  String? _locationError;

  @override
  void initState() {
    super.initState();
    _catalogService = widget.catalogService ?? CatalogService();
    _ownsCatalogService = widget.catalogService == null;
    _refreshCatalog();
    _detectLocation();
  }

  Future<void> _detectLocation() async {
    if (_isDetectingLocation) {
      return;
    }

    setState(() {
      _isDetectingLocation = true;
      _locationError = null;
    });

    final location = await detectCurrentLocation();
    if (!mounted) {
      return;
    }

    setState(() {
      _detectedLocation = location;
      _isDetectingLocation = false;
      _locationError = location == null
          ? 'Location permission was denied or unavailable.'
          : null;
    });
  }

  Future<void> _refreshCatalog({
    CatalogQuery query = const CatalogQuery(),
  }) async {
    setState(() {
      _isLoadingCatalog = true;
      _catalogError = null;
      _activeQuery = query;
    });

    try {
      final catalog = await _catalogService.fetchCatalog(query: query);
      if (!mounted) {
        return;
      }

      setState(() {
        _catalog = catalog;
        _isLoadingCatalog = false;
        _usingFallback = false;
      });
    } catch (error) {
      if (!mounted) {
        return;
      }

      setState(() {
        if (useCatalogFallback) {
          _catalog = fallbackCatalog;
        }
        _isLoadingCatalog = false;
        _usingFallback = useCatalogFallback;
        _catalogError = error is CatalogException
            ? error.message
            : 'Catalog API is unavailable.';
      });
    }
  }

  Future<void> _searchCatalog(String query) async {
    await Navigator.of(context).push(
      MaterialPageRoute<void>(
        builder: (_) => BncSearchPage(
          initialQuery: query.trim(),
          catalogService: widget.catalogService,
        ),
      ),
    );
  }

  Future<void> _openCategory(String categorySlug) async {
    if (categorySlug == 'clinic' || categorySlug == 'doctor-booking') {
      await Navigator.of(context).push(
        MaterialPageRoute<void>(builder: (_) => const BncDoctorBookingPage()),
      );
      return;
    }

    await Navigator.of(context).push(
      MaterialPageRoute<void>(
        builder: (_) => BncCategoryBrowsePage(
          initialCategorySlug: categorySlug,
          initialCategories: _catalog.categories,
          showAllCategoriesPanel: true,
          catalogService: widget.catalogService,
        ),
      ),
    );
  }

  @override
  void dispose() {
    if (_ownsCatalogService) {
      _catalogService.close();
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final usePreviewShell = constraints.maxWidth > 500;

        Widget screen = _MobileHomeScreen(
          catalog: _catalog,
          activeQuery: _activeQuery,
          detectedLocation: _detectedLocation,
          isLoadingCatalog: _isLoadingCatalog,
          usingFallback: _usingFallback,
          isDetectingLocation: _isDetectingLocation,
          catalogError: _catalogError,
          locationError: _locationError,
          onRefresh: () => _refreshCatalog(query: _activeQuery),
          onDetectLocation: _detectLocation,
          onSearch: _searchCatalog,
          onCategorySelected: _openCategory,
          showPreviewChrome: usePreviewShell,
        );

        if (usePreviewShell) {
          screen = Center(
            child: Container(
              width: 430,
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: Colors.black,
                borderRadius: BorderRadius.circular(44),
                boxShadow: const [
                  BoxShadow(
                    color: Color(0x29000000),
                    blurRadius: 34,
                    offset: Offset(0, 20),
                  ),
                ],
              ),
              child: ClipRRect(
                borderRadius: BorderRadius.circular(36),
                child: screen,
              ),
            ),
          );
        }

        return Scaffold(
          backgroundColor: usePreviewShell ? brandSoft : brandCanvas,
          body: SafeArea(top: !usePreviewShell, bottom: false, child: screen),
        );
      },
    );
  }
}

