}

class BncCategoryBrowsePage extends StatefulWidget {
  const BncCategoryBrowsePage({
    super.key,
    required this.initialCategorySlug,
    required this.initialCategories,
    this.showAllCategoriesPanel = false,
    this.catalogService,
  });

  final String initialCategorySlug;
  final List<CategoryItem> initialCategories;
  final bool showAllCategoriesPanel;
  final CatalogService? catalogService;

  @override
  State<BncCategoryBrowsePage> createState() => _BncCategoryBrowsePageState();
}

class _BncCategoryBrowsePageState extends State<BncCategoryBrowsePage> {
  late final CatalogService _catalogService;
  late final bool _ownsCatalogService;

  late String _categorySlug;
  CatalogData? _catalog;
  Timer? _autoRefreshTimer;
  bool _isLoading = true;
  bool _isAutoRefreshing = false;
  bool _usingFallback = false;
  String? _error;

  @override
  void initState() {
    super.initState();
    _catalogService = widget.catalogService ?? CatalogService();
    _ownsCatalogService = widget.catalogService == null;
    _categorySlug = widget.initialCategorySlug;
    _loadCategory(_categorySlug);
    _autoRefreshTimer = Timer.periodic(
      const Duration(seconds: 12),
      (_) => _refreshCategorySilently(),
    );
  }

  Future<void> _loadCategory(String slug) async {
    setState(() {
      _categorySlug = slug;
      _isLoading = true;
      _error = null;
    });

    try {
      final catalog = await _catalogService.fetchCatalog(
        query: CatalogQuery(categorySlug: slug),
      );
      if (!mounted) {
        return;
      }

      setState(() {
        _catalog = catalog;
        _isLoading = false;
        _usingFallback = false;
      });
    } catch (error) {
      if (!mounted) {
        return;
      }

      setState(() {
        _catalog = useCatalogFallback ? _fallbackCategoryCatalog(slug) : null;
        _isLoading = false;
        _usingFallback = useCatalogFallback;
        _error = error is CatalogException
            ? error.message
            : 'Category could not be loaded.';
      });
    }
  }

  Future<void> _refreshCategorySilently() async {
    if (_isAutoRefreshing || !mounted) {
      return;
    }

    _isAutoRefreshing = true;
    final slug = _categorySlug;
    try {
      final catalog = await _catalogService.fetchCatalog(
        query: CatalogQuery(categorySlug: slug),
      );
      if (!mounted || slug != _categorySlug) {
        return;
      }

      setState(() {
        _catalog = catalog;
        _usingFallback = false;
        _error = null;
      });
    } catch (_) {
      // Keep the current screen stable if the live API is briefly unavailable.
    } finally {
      _isAutoRefreshing = false;
    }
  }

  @override
  void dispose() {
    _autoRefreshTimer?.cancel();
    if (_ownsCatalogService) {
      _catalogService.close();
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final catalog = _catalog;
    final categories = catalog?.categories.isNotEmpty == true
        ? catalog!.categories
        : widget.initialCategories;
    final categoryName = _categoryNameForSlug(categories, _categorySlug);
    final businesses = catalog?.all ?? const <BusinessItem>[];
    final shopCards = _shopSpecsFromBusinesses(businesses, const []);
    final latestOffers = _latestOffersForCategory(_categorySlug, categoryName);
    final categoryServices = _categoryServiceItems(_categorySlug);

    return _BncPhoneSizedRoute(
      child: Scaffold(
        backgroundColor: brandSurface,
        body: SafeArea(
          child: RefreshIndicator(
            color: brandNavy,
            onRefresh: () => _loadCategory(_categorySlug),
            child: CustomScrollView(
              physics: const AlwaysScrollableScrollPhysics(),
              slivers: [
                SliverToBoxAdapter(
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(16, 10, 16, 0),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        _BncCategorySimpleTopBar(title: categoryName),
                        const SizedBox(height: 12),
                        if (categories.isEmpty && _isLoading)
                          const _BncCategorySkeleton()
                        else if (categories.isEmpty)
                          const _BncEmptyPanel(
                            icon: Icons.category_outlined,
                            title: 'No categories yet',
                            text:
                                'Categories added from the web admin will appear here.',
                          )
                        else if (widget.showAllCategoriesPanel)
                          _BncAllCategoryAccessPanel(
                            categories: _categorySpecsFromCategories(
                              categories,
                              _categorySlug,
                            ),
                            activeSlug: _categorySlug,
                            services: categoryServices,
                            onCategorySelected: _loadCategory,
                            onServiceOpen: (item) {
                              Navigator.of(context).push(
                                MaterialPageRoute<void>(
                                  builder: (_) => _BncCategoryServiceDetailPage(
                                    categoryName: categoryName,
                                    item: item,
                                    shops: shopCards,
                                    catalogService: _catalogService,
                                  ),
                                ),
                              );
                            },
                          )
                        else ...[
                          if (latestOffers.isNotEmpty) ...[
                            _BncSectionTitle(
                              title: '$categoryName latest offers',
                            ),
                            const SizedBox(height: 12),
                            _HorizontalOfferImageScroller(
                              offers: latestOffers,
                              shops: shopCards,
                              catalogService: _catalogService,
                            ),
                            const SizedBox(height: 24),
                          ],
                          _BncSectionTitle(title: 'Explore $categoryName'),
                          const SizedBox(height: 12),
                          _CategoryServiceHorizontalScroller(
                            items: categoryServices,
                            selectedTitle: categoryServices.isEmpty
                                ? ''
                                : categoryServices.first.title,
                            onSelected: (item) {
                              Navigator.of(context).push(
                                MaterialPageRoute<void>(
                                  builder: (_) => _BncCategoryServiceDetailPage(
                                    categoryName: categoryName,
                                    item: item,
                                    shops: shopCards,
                                    catalogService: _catalogService,
                                  ),
                                ),
                              );
                            },
                          ),
                          if (categoryServices.isNotEmpty) ...[
                            const SizedBox(height: 24),
                            _BncSectionTitle(
                              title: '$categoryName product best deals',
                            ),
                            const SizedBox(height: 12),
                            _ProductDealsHorizontalScroller(
                              item: categoryServices.first,
                              categoryName: categoryName,
                              deals: _bestProductDealsForCategory(
                                categoryName,
                                categoryServices,
                              ),
                              shops: shopCards,
                              catalogService: _catalogService,
                            ),
                          ],
                        ],
                        if (widget.showAllCategoriesPanel) ...[
                          const SizedBox(height: 24),
                          _BncSectionTitle(
                            title: latestOffers.isNotEmpty
                                ? '$categoryName latest offers'
                                : '$categoryName businesses',
                          ),
                          const SizedBox(height: 12),
                          if (latestOffers.isNotEmpty)
                            _BncCategoryLatestOfferRail(
                              offers: latestOffers,
                              shops: shopCards,
                              catalogService: _catalogService,
                            )
                          else if (_isLoading && shopCards.isEmpty)
                            const _BncGridSkeleton()
                          else if (shopCards.isEmpty)
                            _BncEmptyPanel(
                              icon: Icons.storefront_outlined,
                              title: 'No businesses found',
                              text: _error == null
                                  ? 'Listings for this category will appear here once they are added.'
                                  : 'Pull to refresh or try another category.',
                            )
                          else
                            _BncShopGrid(
                              shops: shopCards,
                              catalogService: _catalogService,
                            ),
                        ],
                        const SizedBox(height: 110),
                      ],
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

