class _BncAllCategoryAccessPanel extends StatelessWidget {
  const _BncAllCategoryAccessPanel({
    required this.categories,
    required this.activeSlug,
    required this.services,
    required this.onCategorySelected,
    required this.onServiceOpen,
  });

  final List<_BncCategorySpec> categories;
  final String activeSlug;
  final List<_CategoryServiceSpec> services;
  final Future<void> Function(String categorySlug) onCategorySelected;
  final ValueChanged<_CategoryServiceSpec> onServiceOpen;

  @override
  Widget build(BuildContext context) {
    final visibleServices = services.take(8).toList();
    final activeCategory = categories.firstWhere(
      (item) => _normalizeKey(item.slug) == _normalizeKey(activeSlug),
      orElse: () => _BncCategorySpec(
        'Category',
        Icons.category_outlined,
        brandNavy,
        const Color(0xFFEAF1FF),
        slug: activeSlug,
      ),
    );

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        SizedBox(
          height: 42,
          child: ListView.separated(
            scrollDirection: Axis.horizontal,
            physics: const BouncingScrollPhysics(),
            itemCount: categories.length,
            separatorBuilder: (_, _) => const SizedBox(width: 8),
            itemBuilder: (context, index) {
              final item = categories[index];
              final selected =
                  _normalizeKey(item.slug) == _normalizeKey(activeSlug);
              return ChoiceChip(
                label: Text(item.label),
                selected: selected,
                onSelected: item.slug.isEmpty
                    ? null
