String? _categorySideAsset(_BncCategorySpec item) {
  final slug = item.slug.isEmpty ? item.label : item.slug;
  final services = _categoryServiceItems(slug);
  if (services.isEmpty) {
    return null;
  }
  return services.first.asset;
}

