class _BncUniversalSearchResults extends StatelessWidget {
  const _BncUniversalSearchResults({
    required this.results,
    required this.categories,
    this.catalogService,
  });

  final List<_BncSearchResultSpec> results;
  final List<CategoryItem> categories;
  final CatalogService? catalogService;

  void _openResult(BuildContext context, _BncSearchResultSpec result) {
    switch (result.kind) {
      case _BncSearchResultKind.shop:
        final shop = result.shop;
        if (shop != null) {
          _openBusinessDetail(context, shop, catalogService: catalogService);
        }
        return;
      case _BncSearchResultKind.subcategory:
        final item = result.service;
        if (item != null) {
          Navigator.of(context).push(
            MaterialPageRoute<void>(
              builder: (_) => _BncCategoryServiceDetailPage(
                categoryName: result.categoryName,
                item: item,
                shops: _allBncShops,
                catalogService: catalogService,
              ),
            ),
          );
        }
        return;
    }
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: List.generate(results.length, (index) {
        final result = results[index];
        return Padding(
          padding: EdgeInsets.only(
            bottom: index == results.length - 1 ? 0 : 10,
          ),
          child: _BncUniversalSearchCard(
            result: result,
            onTap: () => _openResult(context, result),
          ),
        );
      }),
    );
  }
}

