enum _BncSearchResultKind { shop, subcategory }

class _BncSearchResultSpec {
  const _BncSearchResultSpec({
    required this.kind,
    required this.typeLabel,
    required this.title,
    required this.subtitle,
    required this.asset,
    required this.icon,
    required this.tint,
    this.categorySlug = '',
    this.categoryName = '',
    this.shop,
    this.service,
  });

  final _BncSearchResultKind kind;
  final String typeLabel;
  final String title;
  final String subtitle;
  final String asset;
  final IconData icon;
  final Color tint;
  final String categorySlug;
  final String categoryName;
  final _BncShopSpec? shop;
  final _CategoryServiceSpec? service;
}

List<_BncSearchResultSpec> _buildUniversalSearchResults({
  required String query,
  required List<CategoryItem> categories,
  required List<_BncShopSpec> shops,
}) {
  final normalizedQuery = query.trim().toLowerCase();
  if (normalizedQuery.isEmpty) {
    return const <_BncSearchResultSpec>[];
  }

  bool matches(String text) => text.toLowerCase().contains(normalizedQuery);
  final results = <_BncSearchResultSpec>[];

  for (final shop in shops) {
    final haystack = [
      shop.name,
      shop.category,
      shop.description,
      shop.distance,
      shop.badge,
      shop.address?.area ?? '',
      shop.contact.phone,
      shop.contact.whatsapp,
    ].join(' ');
    if (matches(haystack)) {
      results.add(
        _BncSearchResultSpec(
          kind: _BncSearchResultKind.shop,
          typeLabel: 'Shop',
          title: shop.name,
          subtitle: '${shop.category} • ${shop.distance}',
          asset: shop.asset,
          icon: Icons.storefront_outlined,
          tint: const Color(0xFFEAF1FF),
          shop: shop,
        ),
      );
    }
  }

  final categorySpecs = _categorySpecsFromCategories(categories, '');
  for (final category in categorySpecs) {
    final services = _categoryServiceItems(category.slug);
    for (final service in services) {
      final serviceHaystack = [
        category.label,
        service.title,
        service.subtitle,
        service.badge,
        ...service.tags,
      ].join(' ');
      if (matches(serviceHaystack)) {
        results.add(
          _BncSearchResultSpec(
            kind: _BncSearchResultKind.subcategory,
            typeLabel: 'Product / Service',
            title: service.title,
            subtitle: '${category.label} • ${service.subtitle}',
            asset: service.asset,
            icon: Icons.category_outlined,
            tint: const Color(0xFFEAF7EF),
            categorySlug: category.slug,
            categoryName: category.label,
            service: service,
          ),
        );
      }
    }
  }

  return results.take(40).toList();
}

CatalogData _fallbackSearchCatalog(String query) {
  final normalizedQuery = query.trim().toLowerCase();
  if (normalizedQuery.isEmpty) {
    return const CatalogData(
      categories: [],
      featured: [],
      popular: [],
      all: [],
      stats: CatalogStats(
        categories: 0,
        businesses: 0,
        trusted: 0,
        happyUsers: '0',
      ),
    );
  }

  final matches = fallbackCatalog.all.where((business) {
    final haystack = [
      business.name,
      business.shortDescription,
      business.categoryName,
      business.area,
      business.city,
      business.searchText,
      ...business.tags,
    ].join(' ').toLowerCase();

    return haystack.contains(normalizedQuery);
  }).toList();

  return CatalogData(
    categories: fallbackCatalog.categories,
    featured: matches.where((business) => business.isFeatured).toList(),
    popular: matches.where((business) => business.isPopular).toList(),
    all: matches,
    stats: fallbackCatalog.stats,
    filters: CatalogFilters(query: query),
  );
}

