class _BusinessDetailHero extends StatelessWidget {
  const _BusinessDetailHero({
    required this.title,
    required this.category,
    required this.description,
    required this.rating,
    required this.reviews,
    required this.distance,
    required this.address,
    required this.image,
    required this.imageUrl,
    required this.isFeatured,
    required this.isPopular,
    required this.isLoading,
    required this.error,
    required this.onBack,
    required this.onRetry,
  });

  final String title;
  final String category;
  final String description;
  final String rating;
  final String reviews;
  final String distance;
  final String address;
  final String image;
  final String imageUrl;
  final bool isFeatured;
  final bool isPopular;
  final bool isLoading;
  final String? error;
  final VoidCallback onBack;
  final Future<void> Function() onRetry;

  @override
  Widget build(BuildContext context) {
    return Container(
      color: brandNavyDeep,
      child: Stack(
        children: [
          SizedBox(
            height: 390,
            width: double.infinity,
            child: _AssetImageFill(
              asset: image,
              imageUrl: imageUrl,
              darken: true,
            ),
          ),
          Positioned.fill(
            child: DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  colors: [
                    brandNavyDeep.withValues(alpha: 0.90),
                    brandNavy.withValues(alpha: 0.44),
                    Colors.transparent,
                    brandNavyDeep.withValues(alpha: 0.96),
                  ],
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  stops: const [0, 0.34, 0.58, 1],
                ),
              ),
            ),
          ),
          Positioned(
            top: 8,
            left: 8,
            child: _CircleIconButton(
              icon: Icons.arrow_back_rounded,
              onTap: onBack,
            ),
          ),
          Positioned(
            top: 12,
            right: 12,
            child: _BusinessPill(label: category, color: brandGold),
          ),
          Positioned(
            left: 16,
            right: 16,
            bottom: 22,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: [
                    if (isFeatured)
                      const _BusinessPill(
                        label: 'Featured',
                        color: Color(0xFF2469D6),
                        foreground: Colors.white,
                      ),
                    if (isPopular)
                      const _BusinessPill(
                        label: 'Popular',
                        color: Color(0xFFF4A51C),
                      ),
                    _BusinessMetricPill(
                      icon: Icons.star_rounded,
                      label: '$rating ($reviews)',
                    ),
                    _BusinessMetricPill(
                      icon: Icons.location_on_outlined,
                      label: distance,
                    ),
                  ],
                ),
                const SizedBox(height: 14),
                Text(
                  title,
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: Colors.white,
                    fontSize: 30,
                    height: 1.02,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 9),
                Text(
                  description.isEmpty
                      ? 'Local shop details, contact and location in one place.'
                      : description,
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    color: Colors.white.withValues(alpha: 0.86),
                    fontSize: 13,
                    height: 1.35,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const SizedBox(height: 12),
                Row(
                  children: [
                    const Icon(
                      Icons.place_outlined,
                      color: Colors.white,
                      size: 17,
                    ),
                    const SizedBox(width: 6),
                    Expanded(
                      child: Text(
                        address,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          color: Colors.white.withValues(alpha: 0.88),
                          fontSize: 12,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                    ),
                  ],
                ),
                if (isLoading || error != null) ...[
                  const SizedBox(height: 12),
                  _BusinessInlineStatus(
                    isLoading: isLoading,
                    error: error,
                    onRetry: onRetry,
                  ),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }
}

