List<_BncOfferSpec> _latestOffersForCategory(String slug, String categoryName) {
  final key = _normalizeKey('$slug $categoryName');
  if (key.contains('grocery')) {
    return _groceryLatestOffers;
  }
  if (key.contains('restaurant')) {
    return _restaurantLatestOffers;
  }
  if (key.contains('beauty')) {
    return _beautyLatestOffers;
  }
  if (key.contains('tailor') || key.contains('textile')) {
    return _tailorLatestOffers;
  }
  if (key.contains('electronics') || key.contains('mobile')) {
    return _electronicsLatestOffers;
  }
  if (key.contains('homeservices') || key.contains('home')) {
    return _homeServiceLatestOffers;
  }
  if (key.contains('pharmacy') || key.contains('clinic')) {
    return _pharmacyLatestOffers;
  }
  if (key.contains('gift') || key.contains('stationery')) {
    return _giftsStationeryLatestOffers;
  }
  return const [];
}

