class _BncNotificationSpec {
  const _BncNotificationSpec({
    required this.icon,
    required this.title,
    required this.message,
    required this.time,
    required this.type,
    required this.accent,
    required this.actionLabel,
    required this.route,
    this.asset = '',
    this.unread = false,
  });

  final IconData icon;
  final String title;
  final String message;
  final String time;
  final String type;
