List<(IconData, String)> _ecosystemNextStepsFor(String title) {
  switch (title) {
    case 'Business Card':
      return const [
        (Icons.add_business_outlined, 'Details'),
        (Icons.qr_code_2_rounded, 'QR'),
        (Icons.share_outlined, 'Share'),
      ];
    case 'B2B Network':
      return const [
        (Icons.search_rounded, 'Find'),
