  void initState() {
    super.initState();
    nameController = TextEditingController(text: widget.name);
    phoneController = TextEditingController(text: widget.phone);
    emailController = TextEditingController(text: widget.email);
    areaController = TextEditingController(text: widget.area);
    selectedPhotoBytes = widget.photoBytes;
  }

  @override
  void dispose() {
    nameController.dispose();
    phoneController.dispose();
    emailController.dispose();
    areaController.dispose();
    super.dispose();
  }

  Future<void> _chooseProfilePhoto() async {
    try {
      final picked = await ImagePicker().pickImage(
        source: ImageSource.gallery,
        imageQuality: 82,
        maxWidth: 900,
      );
      if (picked == null) return;
      final bytes = await picked.readAsBytes();
      if (!mounted) return;
      setState(() => selectedPhotoBytes = bytes);
    } catch (_) {
      if (!mounted) return;
      _showBncSnack(context, 'Could not open gallery.');
    }
  }

  void _saveProfile() {
    final nextName = nameController.text.trim();
    if (nextName.isEmpty) {
      _showBncSnack(context, 'Please enter your name.');
      return;
    }

    Navigator.of(context).pop(
      _BncProfileEditResult(
        name: nextName,
        phone: phoneController.text.trim(),
        email: emailController.text.trim(),
        area: areaController.text.trim().isEmpty
            ? 'Kozhikode, Kerala'
            : areaController.text.trim(),
        photoBytes: selectedPhotoBytes,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final initial = nameController.text.trim().isEmpty
        ? 'B'
        : nameController.text.trim()[0].toUpperCase();

    return _BncPhoneSizedRoute(
      child: Scaffold(
        backgroundColor: brandSurface,
        body: SafeArea(
          child: CustomScrollView(
            physics: const BouncingScrollPhysics(),
            slivers: [
              SliverToBoxAdapter(
                child: Container(
                  padding: const EdgeInsets.fromLTRB(8, 8, 14, 18),
                  decoration: const BoxDecoration(
                    gradient: LinearGradient(
                      colors: [brandNavyDeep, brandNavy, brandNavyBright],
                      begin: Alignment.topLeft,
                      end: Alignment.bottomRight,
                    ),
                    borderRadius: BorderRadius.vertical(
                      bottom: Radius.circular(26),
                    ),
                  ),
                  child: Row(
                    children: [
                      IconButton(
                        onPressed: () => Navigator.of(context).pop(),
                        visualDensity: VisualDensity.compact,
                        icon: const Icon(
                          Icons.arrow_back,
                          color: Colors.white,
                          size: 22,
                        ),
                      ),
                      const Expanded(
                        child: Text(
                          'Edit profile',
                          style: TextStyle(
                            color: Colors.white,
                            fontSize: 20,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ),
                      Container(
                        width: 38,
                        height: 38,
                        decoration: BoxDecoration(
                          color: brandGold,
                          borderRadius: BorderRadius.circular(14),
                        ),
                        child: const Icon(
                          Icons.person_outline,
                          color: brandNavy,
                          size: 21,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
              SliverPadding(
                padding: const EdgeInsets.fromLTRB(12, 14, 12, 96),
                sliver: SliverList(
                  delegate: SliverChildListDelegate([
                    Container(
                      width: double.infinity,
                      padding: const EdgeInsets.all(14),
                      decoration: BoxDecoration(
                        color: brandNavy,
                        borderRadius: BorderRadius.circular(22),
                        boxShadow: [
                          BoxShadow(
                            color: brandNavy.withValues(alpha: 0.16),
                            blurRadius: 18,
                            offset: const Offset(0, 8),
                          ),
                        ],
                      ),
                      child: Row(
                        children: [
                          Container(
                            width: 78,
                            height: 78,
                            clipBehavior: Clip.antiAlias,
                            decoration: BoxDecoration(
                              color: Colors.white,
                              borderRadius: BorderRadius.circular(24),
                              border: Border.all(color: brandGold, width: 2),
                            ),
                            child: selectedPhotoBytes == null
                                ? Center(
                                    child: Text(
                                      initial,
                                      style: const TextStyle(
                                        color: brandNavy,
                                        fontSize: 32,
                                        fontWeight: FontWeight.w900,
                                      ),
                                    ),
                                  )
                                : Image.memory(
                                    selectedPhotoBytes!,
                                    fit: BoxFit.cover,
                                  ),
                          ),
                          const SizedBox(width: 12),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                const Text(
                                  'Profile photo',
                                  style: TextStyle(
                                    color: Colors.white,
                                    fontSize: 16,
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                                const SizedBox(height: 4),
                                const Text(
                                  'Pick from gallery or files.',
                                  style: TextStyle(
                                    color: brandHeroText,
                                    fontSize: 11.5,
                                    height: 1.25,
                                    fontWeight: FontWeight.w700,
                                  ),
                                ),
                                const SizedBox(height: 10),
                                Wrap(
                                  spacing: 8,
                                  runSpacing: 8,
                                  children: [
                                    _BncMiniSheetButton(
                                      icon: Icons.photo_library_outlined,
                                      label: 'Choose photo',
                                      onTap: _chooseProfilePhoto,
                                    ),
                                    if (selectedPhotoBytes != null)
                                      _BncMiniSheetButton(
                                        icon: Icons.close_rounded,
                                        label: 'Remove',
                                        onTap: () => setState(
                                          () => selectedPhotoBytes = null,
                                        ),
                                      ),
                                  ],
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(height: 14),
                    _BncSettingsTextField(
                      controller: nameController,
                      label: 'Name',
                      icon: Icons.person_outline,
                    ),
                    _BncSettingsTextField(
                      controller: phoneController,
                      label: 'Phone number',
                      icon: Icons.phone_outlined,
                      keyboardType: TextInputType.phone,
                    ),
                    _BncSettingsTextField(
                      controller: emailController,
                      label: 'Email address',
                      icon: Icons.alternate_email_rounded,
                      keyboardType: TextInputType.emailAddress,
                    ),
                    _BncSettingsTextField(
                      controller: areaController,
                      label: 'Location',
                      icon: Icons.location_on_outlined,
                    ),
                    const SizedBox(height: 8),
                    _BncSettingsPrimaryButton(
                      icon: Icons.check_rounded,
                      label: 'Save profile',
                      onTap: _saveProfile,
                    ),
                  ]),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

