class _BncSearchBox extends StatefulWidget {
  const _BncSearchBox({required this.initialQuery, required this.onSearch});

  final String initialQuery;
  final Future<void> Function(String query) onSearch;

  @override
  State<_BncSearchBox> createState() => _BncSearchBoxState();
}

class _BncSearchBoxState extends State<_BncSearchBox> {
  late final TextEditingController _controller;

  @override
  void initState() {
    super.initState();
    _controller = TextEditingController(text: widget.initialQuery);
  }

  @override
  void didUpdateWidget(covariant _BncSearchBox oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.initialQuery != widget.initialQuery &&
        _controller.text != widget.initialQuery) {
      _controller.text = widget.initialQuery;
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  Future<void> _submit() {
    return widget.onSearch(_controller.text.trim());
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(6),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(18),
        boxShadow: const [
          BoxShadow(
            color: Color(0x24000000),
            blurRadius: 18,
            offset: Offset(0, 8),
          ),
        ],
      ),
      child: Row(
        children: [
          const SizedBox(width: 8),
          const Icon(Icons.search, color: brandMuted, size: 25),
          const SizedBox(width: 10),
          Expanded(
            child: TextField(
              controller: _controller,
              minLines: 1,
              maxLines: 1,
              textInputAction: TextInputAction.search,
              onSubmitted: (_) => _submit(),
              decoration: const InputDecoration(
                border: InputBorder.none,
                isDense: true,
                hintText: 'Search shops, products, services or deals',
                hintStyle: TextStyle(
                  color: brandMuted,
                  fontSize: 13.5,
                  fontWeight: FontWeight.w700,
                ),
              ),
              style: const TextStyle(
                color: brandNavy,
                fontSize: 13.5,
                fontWeight: FontWeight.w800,
              ),
            ),
          ),
          const SizedBox(width: 8),
          FilledButton(
            style: FilledButton.styleFrom(
              backgroundColor: brandGold,
              foregroundColor: brandNavy,
              padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 14),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(14),
              ),
            ),
            onPressed: _submit,
            child: const Text(
              'Search',
              style: TextStyle(fontSize: 13, fontWeight: FontWeight.w900),
