          width: 86,
          child: _BncCategoryTile(
            item: item,
            onTap: item.slug.isEmpty
                ? null
                : () {
                    if (_normalizeKey(item.label) == 'doctorbooking' ||
                        _normalizeKey(item.slug) == 'doctorbooking') {
                      onDoctorBooking?.call();
