class _BncSlidingRail extends StatefulWidget {
  const _BncSlidingRail({
    required this.height,
    required this.itemCount,
    required this.itemBuilder,
    this.autoSlide = false,
    this.gap = 12,
  });

  final double height;
  final int itemCount;
  final double gap;
  final bool autoSlide;
  final IndexedWidgetBuilder itemBuilder;

  @override
  State<_BncSlidingRail> createState() => _BncSlidingRailState();
}

class _BncSlidingRailState extends State<_BncSlidingRail> {
  final ScrollController _controller = ScrollController();
  late final PageController _pageController;
  Timer? _autoSlideTimer;
  int _currentPage = 0;

  @override
  void initState() {
    super.initState();
    _pageController = PageController();
    _syncAutoSlideTimer();
  }

  @override
  void didUpdateWidget(covariant _BncSlidingRail oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.autoSlide != widget.autoSlide ||
        oldWidget.itemCount != widget.itemCount) {
      _syncAutoSlideTimer();
    }
  }

  @override
  void dispose() {
    _autoSlideTimer?.cancel();
    _pageController.dispose();
    _controller.dispose();
    super.dispose();
  }

  void _syncAutoSlideTimer() {
    _autoSlideTimer?.cancel();
    _autoSlideTimer = null;

    if (!widget.autoSlide || widget.itemCount < 2) {
      return;
    }

    _autoSlideTimer = Timer.periodic(const Duration(seconds: 3), (_) {
      if (!mounted) {
        return;
      }

      final nextPage = (_currentPage + 1) % widget.itemCount;
      _pageController.animateToPage(
        nextPage,
        duration: const Duration(milliseconds: 520),
        curve: Curves.easeOutCubic,
      );
    });
  }

  @override
  Widget build(BuildContext context) {
    if (widget.autoSlide) {
      return SizedBox(
        height: widget.height,
        child: PageView.builder(
          controller: _pageController,
          physics: const BouncingScrollPhysics(),
          itemCount: widget.itemCount,
          onPageChanged: (index) {
            _currentPage = index;
          },
          itemBuilder: widget.itemBuilder,
        ),
      );
    }

    return SizedBox(
      height: widget.height,
      child: ListView.separated(
        controller: _controller,
        physics: const BouncingScrollPhysics(),
        scrollDirection: Axis.horizontal,
        itemCount: widget.itemCount,
        separatorBuilder: (_, _) => SizedBox(width: widget.gap),
        itemBuilder: widget.itemBuilder,
      ),
    );
  }
}

