class _BncCategoryServiceDetailPage extends StatefulWidget {
  const _BncCategoryServiceDetailPage({
    super.key,
    required this.categoryName,
    required this.item,
    required this.shops,
    this.catalogService,
  });

  final String categoryName;
  final _CategoryServiceSpec item;
  final List<_BncShopSpec> shops;
  final CatalogService? catalogService;

  @override
  State<_BncCategoryServiceDetailPage> createState() =>
      _BncCategoryServiceDetailPageState();
}

class _BncCategoryServiceDetailPageState
    extends State<_BncCategoryServiceDetailPage> {
  late _CategoryServiceSpec _currentItem;

  @override
  void initState() {
    super.initState();
    _currentItem = widget.item;
  }

  @override
  Widget build(BuildContext context) {
    if (_normalizeKey(widget.categoryName) == 'doctorbooking') {
      return const BncDoctorBookingPage();
    }
    if (_normalizeKey(widget.categoryName) == 'mobile' &&
        _normalizeKey(_currentItem.title) == 'mobiles') {
      return _BncMobileBrandStorePage(shops: widget.shops);
    }
    if (_isMobileRepairRoute(widget.categoryName, _currentItem.title)) {
      return _BncMobileRepairPage(
        shops: widget.shops,
        catalogService: widget.catalogService,
      );
    }
    if (_isMobileAccessoriesRoute(widget.categoryName, _currentItem.title)) {
      return _BncMobileAccessoriesPage(
        shops: widget.shops,
        catalogService: widget.catalogService,
      );
    }

    final deals = _productDealsForCategory(widget.categoryName, _currentItem);
    final isElectronicsRepairSection = _isElectronicsRepairRoute(
      widget.categoryName,
      _currentItem.title,
    );
    final productCards = deals
        .map(
          (deal) => _BncProductSaleSpec(
            name: deal.title,
            asset: deal.asset,
            shopName: isElectronicsRepairSection
                ? 'Tech World Service Center'
                : _shopNameForCategory(widget.categoryName, widget.shops),
            discount: deal.discount,
            oldPrice: _oldPriceForProductName(deal.title),
            price: _priceForProductName(deal.title),
            variants: _variantsForProductName(deal.title),
            subcategoryName: deal.subcategoryName,
            badge: _badgeForProductName(deal.title),
          ),
        )
        .toList();

    return _BncPhoneSizedRoute(
      child: Scaffold(
        backgroundColor: Colors.white,
        body: SafeArea(
          child: CustomScrollView(
            physics: const BouncingScrollPhysics(),
            slivers: [
              SliverToBoxAdapter(
                child: Container(
                  color: const Color(0xFFEAF3FF),
                  padding: const EdgeInsets.fromLTRB(6, 8, 8, 10),
                  child: Row(
                    children: [
                      IconButton(
                        onPressed: () => Navigator.of(context).maybePop(),
                        visualDensity: VisualDensity.compact,
                        icon: const Icon(
                          Icons.arrow_back_rounded,
                          color: brandNavy,
                          size: 24,
                        ),
                      ),
                      Expanded(
                        child: Container(
                          height: 48,
                          padding: const EdgeInsets.symmetric(horizontal: 14),
                          decoration: BoxDecoration(
                            color: Colors.white,
                            borderRadius: BorderRadius.circular(24),
                            border: Border.all(color: brandLine),
                          ),
                          child: Row(
                            children: [
                              const Icon(
                                Icons.search_rounded,
                                color: brandMuted,
                                size: 22,
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: Text(
                                  _currentItem.title,
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(
                                    color: brandNavy,
                                    fontSize: 15,
                                    fontWeight: FontWeight.w800,
                                  ),
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
              SliverPadding(
                padding: const EdgeInsets.fromLTRB(10, 12, 10, 96),
                sliver: SliverGrid(
                  gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                    crossAxisCount: 2,
                    crossAxisSpacing: 12,
                    mainAxisSpacing: 18,
                    childAspectRatio: 0.58,
                  ),
                  delegate: SliverChildBuilderDelegate((context, index) {
                    final product = productCards[index];
                    return _BncProductSaleCard(
                      product: product,
                      onTap: () {
                        final itemKey = _normalizeKey(_currentItem.title);
                        final isRestaurantItem =
                            _isRestaurantTopLevelKey(itemKey) ||
                            _isRestaurantFoodGroupKey(itemKey) ||
                            _isRestaurantFoodProductKey(
                              _normalizeKey(product.subcategoryName),
                            );

                        if (isRestaurantItem) {
                          _openSubcategoryShopList(
                            context,
                            categoryName: widget.categoryName,
                            subcategoryName: product.subcategoryName,
                            imageAsset: product.asset,
                            shops: widget.shops,
                            catalogService: widget.catalogService,
                          );
                          return;
                        }

                        if (_opensDirectProductSubcategories(
                          _currentItem.title,
                          product.subcategoryName,
                        )) {
                          _openSubcategoryProductsDirect(
                            context,
                            categoryName: widget.categoryName,
                            subcategoryName: product.subcategoryName,
                            imageAsset: product.asset,
                            shops: widget.shops,
                            catalogService: widget.catalogService,
                          );
                          return;
                        }

                        _openSubcategoryShopList(
                          context,
                          categoryName: widget.categoryName,
                          subcategoryName: product.subcategoryName,
                          imageAsset: product.asset,
                          shops: widget.shops,
                          catalogService: widget.catalogService,
                        );
                      },
                    );
                  }, childCount: productCards.length),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

