class _BncMobileModelDetailPage extends StatefulWidget {
  const _BncMobileModelDetailPage({
    required this.brand,
    required this.model,
    required this.shop,
  });

  final _BncMobileBrandSpec brand;
  final _BncMobileModelSpec model;
  final _BncShopSpec shop;

  @override
  State<_BncMobileModelDetailPage> createState() =>
      _BncMobileModelDetailPageState();
}

class _BncMobileModelDetailPageState extends State<_BncMobileModelDetailPage> {
  late final List<_BncMobileColorOption> _colors;
  late final List<_BncMobileVariantOption> _variants;
  late _BncMobileColorOption _selectedColor;
  late _BncMobileVariantOption _selectedVariant;

  @override
  void initState() {
    super.initState();
    _colors = _mobileColorOptionsFor(widget.model);
    _variants = _mobileVariantOptionsFor(widget.model);
    _selectedColor = _colors.first;
    _selectedVariant = _variants.length > 1 ? _variants[1] : _variants.first;
  }

  @override
  Widget build(BuildContext context) {
    return _BncPhoneSizedRoute(
      child: Scaffold(
        backgroundColor: const Color(0xFFFBF8F2),
        body: SafeArea(
          child: CustomScrollView(
            physics: const BouncingScrollPhysics(),
            slivers: [
              SliverToBoxAdapter(
                child: _BncMobileStoreTopBar(
                  title: widget.model.name,
                  hint: 'Search for products',
                  onBack: () => Navigator.of(context).maybePop(),
                ),
              ),
              SliverToBoxAdapter(
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(14, 14, 14, 12),
                  child: _BncMobileDetailHero(
                    model: widget.model,
                    shop: widget.shop,
                    color: _selectedColor,
                    variant: _selectedVariant,
                  ),
                ),
              ),
              SliverToBoxAdapter(
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(14, 0, 14, 12),
                  child: _BncMobileChoicePanel(
                    model: widget.model,
                    colors: _colors,
                    variants: _variants,
                    selectedColor: _selectedColor,
                    selectedVariant: _selectedVariant,
                    onColorChanged: (color) {
                      setState(() => _selectedColor = color);
                    },
                    onVariantChanged: (variant) {
                      setState(() => _selectedVariant = variant);
                    },
                  ),
                ),
              ),
              SliverToBoxAdapter(
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(14, 4, 14, 12),
                  child: _BncMobileSpecPanel(
                    model: widget.model,
                    color: _selectedColor,
                    variant: _selectedVariant,
                  ),
                ),
              ),
              SliverToBoxAdapter(
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(14, 0, 14, 100),
                  child: _BncMobileShopContactPanel(
                    shop: widget.shop,
                    model: widget.model,
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

