class _BncPlainMobileBrandMark {
  const _BncPlainMobileBrandMark(
    this.label,
    this.color, {
    this.fontSize = 26,
    this.fontWeight = FontWeight.w900,
  });

  final String label;
  final Color color;
  final double fontSize;
  final FontWeight fontWeight;
}

_BncPlainMobileBrandMark _plainMobileBrandMark(String brandName) {
  switch (_normalizeKey(brandName)) {
    case 'samsung':
      return const _BncPlainMobileBrandMark(
        'SAMSUNG',
        Color(0xFF1428A0),
        fontSize: 22,
      );
    case 'apple':
      return const _BncPlainMobileBrandMark(
        'Apple',
        Color(0xFF171717),
        fontSize: 25,
      );
    case 'oneplus':
      return const _BncPlainMobileBrandMark('1+', Color(0xFFF50537));
    case 'redmi':
      return const _BncPlainMobileBrandMark('Redmi', Color(0xFFFF6900));
    case 'vivo':
      return const _BncPlainMobileBrandMark('vivo', Color(0xFF315FFF));
    case 'oppo':
      return const _BncPlainMobileBrandMark('OPPO', Color(0xFF008D46));
    case 'realme':
      return const _BncPlainMobileBrandMark('realme', Color(0xFFFFC915));
    case 'motorola':
      return const _BncPlainMobileBrandMark('M', Color(0xFF122B7B));
    case 'nothing':
      return const _BncPlainMobileBrandMark(
        'NOTHING',
        Color(0xFF101010),
        fontSize: 21,
      );
    case 'googlepixel':
      return const _BncPlainMobileBrandMark('Pixel', Color(0xFF4285F4));
    case 'iqoo':
      return const _BncPlainMobileBrandMark('iQOO', Color(0xFFFFB000));
    case 'poco':
      return const _BncPlainMobileBrandMark('POCO', Color(0xFF111111));
    case 'lava':
      return const _BncPlainMobileBrandMark('LAVA', Color(0xFFE21B23));
    case 'infinix':
      return const _BncPlainMobileBrandMark('Infinix', Color(0xFF0A0A0A));
    case 'tecno':
      return const _BncPlainMobileBrandMark('TECNO', Color(0xFF1E63FF));
    case 'nokia':
      return const _BncPlainMobileBrandMark('NOKIA', Color(0xFF124191));
    case 'honor':
      return const _BncPlainMobileBrandMark('HONOR', Color(0xFF0D43A8));
    default:
      return _BncPlainMobileBrandMark(brandName, brandNavy, fontSize: 22);
  }
}

