class _BncMobileModelImage extends StatelessWidget {
  const _BncMobileModelImage({required this.model, required this.fit});

  final _BncMobileModelSpec model;
  final BoxFit fit;

  @override
  Widget build(BuildContext context) {
    final realAsset = _mobileModelRealAsset(model.brand, model.name);
    if (realAsset != null) {
      return _BncMobileModelAssetImage(asset: realAsset, fit: fit);
    }

    final imageUrl = _mobileModelRealImageUrl(model.brand, model.name);
    if (imageUrl != null) {
      return Image.network(
        imageUrl,
        fit: fit,
        errorBuilder: (_, __, ___) =>
            _BncMobileModelAssetImage(asset: model.asset, fit: fit),
      );
    }

    return _BncMobileModelAssetImage(asset: model.asset, fit: fit);
  }
}

