class _BncMobileDetailHeroState extends State<_BncMobileDetailHero> {
  late final PageController _galleryController;
  int _currentGalleryIndex = 0;

  @override
  void initState() {
    super.initState();
    _galleryController = PageController();
  }

  @override
  void dispose() {
    _galleryController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final modelGalleryAsset = widget.color.asset;
    final galleryItems = [
      _BncMobileGalleryItem(
        label: 'Product',
        asset: modelGalleryAsset,
        model: widget.model,
        swatch: widget.color.swatch,
        view: _BncMobileGalleryView.full,
      ),
      _BncMobileGalleryItem(
        label: 'Front',
        asset: widget.color.asset,
        model: widget.model,
        swatch: widget.color.swatch,
        view: _BncMobileGalleryView.front,
      ),
      _BncMobileGalleryItem(
        label: 'Back',
        asset: widget.color.asset,
        model: widget.model,
        swatch: widget.color.swatch,
        view: _BncMobileGalleryView.back,
      ),
      _BncMobileGalleryItem(
        label: 'Side',
        asset: widget.color.asset,
        model: widget.model,
        swatch: widget.color.swatch,
        view: _BncMobileGalleryView.side,
      ),
      _BncMobileGalleryItem(
        label: 'Ports',
        asset: widget.color.asset,
        model: widget.model,
        swatch: widget.color.swatch,
        view: _BncMobileGalleryView.ports,
      ),
    ];

    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(color: brandLine),
      ),
      clipBehavior: Clip.antiAlias,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          SizedBox(
            height: 260,
            child: Stack(
              fit: StackFit.expand,
              children: [
                PageView.builder(
                  controller: _galleryController,
                  physics: const BouncingScrollPhysics(),
                  itemCount: galleryItems.length,
                  onPageChanged: (index) {
                    setState(() => _currentGalleryIndex = index);
                  },
                  itemBuilder: (context, index) {
                    final item = galleryItems[index];
                    return Stack(
                      fit: StackFit.expand,
                      children: [
                        _BncMobileGalleryImage(item: item, fit: BoxFit.contain),
                      ],
                    );
                  },
                ),
                const Positioned(
                  right: 14,
                  top: 14,
                  child: CircleAvatar(
                    radius: 22,
                    backgroundColor: Colors.white,
                    child: Icon(
                      Icons.favorite_border_rounded,
                      color: brandNavy,
                    ),
                  ),
                ),
                Positioned(
                  left: 14,
                  right: 14,
                  bottom: 12,
                  child: _BncMobileGalleryPager(
                    items: galleryItems,
                    selectedIndex: _currentGalleryIndex,
                    onSelected: (index) {
                      _galleryController.animateToPage(
                        index,
                        duration: const Duration(milliseconds: 220),
                        curve: Curves.easeOut,
                      );
                    },
                  ),
                ),
              ],
            ),
          ),
          Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  '${widget.model.name} (${widget.color.name}, ${widget.variant.storage})',
                  style: const TextStyle(
                    color: brandNavy,
                    fontSize: 24,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 6),
                Text(
                  'Available now at ${widget.shop.name}',
                  style: const TextStyle(
                    color: brandMuted,
                    fontSize: 13,
                    fontWeight: FontWeight.w800,
                  ),
                ),
                const SizedBox(height: 12),
                Row(
                  children: [
                    Text(
                      widget.variant.price,
                      style: const TextStyle(
                        color: Color(0xFF009A63),
                        fontSize: 25,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(width: 8),
                    Text(
                      widget.variant.oldPrice,
                      style: const TextStyle(
                        color: brandMuted,
                        fontSize: 15,
                        fontWeight: FontWeight.w800,
                        decoration: TextDecoration.lineThrough,
                      ),
                    ),
                    const SizedBox(width: 8),
                    Text(
                      widget.variant.discount,
                      style: const TextStyle(
                        color: Color(0xFF009A63),
                        fontSize: 14,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 14),
                Row(
                  children: [
                    Expanded(
                      child: _BncProductActionButton(
                        icon: Icons.storefront_rounded,
                        label: 'Visit shop',
                        color: brandNavy,
                        textColor: Colors.white,
                        onTap: () {},
                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: _BncProductActionButton(
                        icon: Icons.delivery_dining_rounded,
                        label: 'Home delivery',
                        color: brandGold,
                        textColor: brandNavy,
                        onTap: () {},
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

enum _BncMobileGalleryView { full, front, back, side, ports }

class _BncMobileGalleryPager extends StatelessWidget {
  const _BncMobileGalleryPager({
    required this.items,
    required this.selectedIndex,
    required this.onSelected,
  });

  final List<_BncMobileGalleryItem> items;
  final int selectedIndex;
  final ValueChanged<int> onSelected;

  @override
  Widget build(BuildContext context) {
    return Align(
      alignment: Alignment.center,
      child: DecoratedBox(
        decoration: BoxDecoration(
          color: Colors.white.withValues(alpha: 0.94),
          borderRadius: BorderRadius.circular(999),
          border: Border.all(color: brandLine),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withValues(alpha: 0.08),
              blurRadius: 16,
              offset: const Offset(0, 6),
            ),
          ],
        ),
        child: SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          physics: const BouncingScrollPhysics(),
          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 5),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              for (var index = 0; index < items.length; index++)
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 2),
                  child: InkWell(
                    onTap: () => onSelected(index),
                    borderRadius: BorderRadius.circular(999),
                    child: AnimatedContainer(
                      duration: const Duration(milliseconds: 180),
                      padding: const EdgeInsets.symmetric(
                        horizontal: 10,
                        vertical: 6,
                      ),
                      decoration: BoxDecoration(
                        color: selectedIndex == index
                            ? brandNavy
                            : Colors.transparent,
                        borderRadius: BorderRadius.circular(999),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Container(
                            width: 6,
                            height: 6,
                            decoration: BoxDecoration(
                              color: selectedIndex == index
                                  ? Colors.white
                                  : brandMuted.withValues(alpha: 0.62),
                              shape: BoxShape.circle,
                            ),
                          ),
                          const SizedBox(width: 6),
                          Text(
                            items[index].label,
                            style: TextStyle(
                              color: selectedIndex == index
                                  ? Colors.white
                                  : brandNavy,
                              fontSize: 11,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }
}

