class _BncMobileModelViewImage extends StatelessWidget {
  const _BncMobileModelViewImage({required this.item, required this.fit});

  final _BncMobileGalleryItem item;
  final BoxFit fit;

  @override
  Widget build(BuildContext context) {
    return switch (item.view) {
      _BncMobileGalleryView.side => _BncMobileSideView(
        swatch: item.swatch ?? brandNavy,
        modelName: item.model?.name ?? item.label,
      ),
      _BncMobileGalleryView.ports => _BncMobilePortsView(
        swatch: item.swatch ?? brandNavy,
        modelName: item.model?.name ?? item.label,
      ),
      _ => _BncMobileModelAssetImage(asset: item.asset, fit: fit),
    };
  }
}

