class _BncMobileChoicePanel extends StatelessWidget {
  const _BncMobileChoicePanel({
    required this.model,
    required this.colors,
    required this.variants,
    required this.selectedColor,
    required this.selectedVariant,
    required this.onColorChanged,
    required this.onVariantChanged,
  });

  final _BncMobileModelSpec model;
  final List<_BncMobileColorOption> colors;
  final List<_BncMobileVariantOption> variants;
  final _BncMobileColorOption selectedColor;
  final _BncMobileVariantOption selectedVariant;
  final ValueChanged<_BncMobileColorOption> onColorChanged;
  final ValueChanged<_BncMobileVariantOption> onVariantChanged;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(22),
        border: Border.all(color: brandLine),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          RichText(
            text: TextSpan(
              style: const TextStyle(
                color: Color(0xFF1F2937),
                fontSize: 15,
                fontWeight: FontWeight.w800,
              ),
              children: [
                const TextSpan(
                  text: 'Selected Color: ',
                  style: TextStyle(fontWeight: FontWeight.w900),
                ),
                TextSpan(text: selectedColor.name),
              ],
            ),
          ),
          const SizedBox(height: 12),
          SizedBox(
            height: 74,
            child: ListView.separated(
              scrollDirection: Axis.horizontal,
              physics: const BouncingScrollPhysics(),
              itemCount: colors.length,
              separatorBuilder: (_, __) => const SizedBox(width: 10),
              itemBuilder: (context, index) {
                final color = colors[index];
                final selected = color.name == selectedColor.name;
                return InkWell(
                  onTap: () => onColorChanged(color),
                  borderRadius: BorderRadius.circular(16),
                  child: AnimatedContainer(
                    duration: const Duration(milliseconds: 180),
                    width: 64,
                    padding: const EdgeInsets.all(4),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(16),
                      border: Border.all(
                        color: selected ? brandNavy : brandLine,
                        width: selected ? 2 : 1,
                      ),
                      boxShadow: selected
                          ? [
                              BoxShadow(
                                color: brandNavy.withValues(alpha: 0.12),
                                blurRadius: 12,
                                offset: const Offset(0, 6),
                              ),
                            ]
                          : null,
                    ),
                    child: ClipRRect(
                      borderRadius: BorderRadius.circular(12),
                      child: Stack(
                        fit: StackFit.expand,
                        children: [
                          ColoredBox(
                            color: Colors.white,
                            child: Padding(
                              padding: const EdgeInsets.all(3),
                              child: _BncMobileModelAssetImage(
                                asset: color.asset,
                                fit: BoxFit.contain,
                              ),
                            ),
                          ),
                          Positioned(
                            right: 5,
                            bottom: 5,
                            child: CircleAvatar(
                              radius: 8,
                              backgroundColor: color.swatch,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                );
              },
            ),
          ),
          const SizedBox(height: 10),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
            decoration: BoxDecoration(
              color: const Color(0xFFFFF1E8),
              borderRadius: BorderRadius.circular(12),
              border: Border.all(color: const Color(0xFFFFC9A8)),
            ),
            child: const Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(
                  Icons.location_off_rounded,
                  color: Color(0xFFC2410C),
                  size: 16,
                ),
                SizedBox(width: 6),
                Text(
                  'Not deliverable in your location',
                  style: TextStyle(
                    color: Color(0xFFC2410C),
                    fontSize: 12.5,
                    fontWeight: FontWeight.w800,
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 20),
          RichText(
            text: TextSpan(
              style: const TextStyle(
                color: Color(0xFF1F2937),
                fontSize: 15,
                fontWeight: FontWeight.w800,
              ),
              children: [
                const TextSpan(
                  text: 'Variant: ',
                  style: TextStyle(fontWeight: FontWeight.w900),
                ),
                TextSpan(text: selectedVariant.storage),
              ],
            ),
          ),
          const SizedBox(height: 12),
          Row(
            children: variants.map((variant) {
              final selected = variant.storage == selectedVariant.storage;
              return Expanded(
                child: Padding(
                  padding: EdgeInsets.only(
                    right: variant == variants.last ? 0 : 10,
                  ),
                  child: InkWell(
                    onTap: () => onVariantChanged(variant),
                    borderRadius: BorderRadius.circular(14),
                    child: AnimatedContainer(
                      duration: const Duration(milliseconds: 180),
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        color: selected
                            ? const Color(0xFFF8FAFC)
                            : Colors.white,
                        borderRadius: BorderRadius.circular(14),
                        border: Border.all(
                          color: selected ? brandNavy : brandLine,
                          width: selected ? 1.4 : 1,
                        ),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            variant.storage,
                            style: const TextStyle(
                              color: Color(0xFF1F2937),
                              fontSize: 14,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          const SizedBox(height: 8),
                          Row(
                            children: [
                              const Icon(
                                Icons.arrow_downward_rounded,
                                color: Color(0xFF009A63),
                                size: 14,
                              ),
                              Text(
                                variant.discount.replaceAll(' OFF', ''),
                                style: const TextStyle(
                                  color: Color(0xFF009A63),
                                  fontSize: 12,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                              const SizedBox(width: 4),
                              Flexible(
                                child: Text(
                                  variant.oldPrice,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(
                                    color: brandMuted,
                                    fontSize: 12,
                                    fontWeight: FontWeight.w700,
                                    decoration: TextDecoration.lineThrough,
                                  ),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 4),
                          Text(
                            variant.price,
                            style: const TextStyle(
                              color: Color(0xFF111827),
                              fontSize: 14,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              );
            }).toList(),
          ),
        ],
      ),
    );
  }
}

