List<_BncMobileColorOption> _mobileColorOptionsFor(_BncMobileModelSpec model) {
  final key = _normalizeKey(model.brand);
  final colors = switch (key) {
    'samsung' => const [
      ('Titanium Black', Color(0xFF111827)),
      ('Navy', Color(0xFF1E3A8A)),
      ('Silver Shadow', Color(0xFFD1D5DB)),
      ('Mint', Color(0xFFA7F3D0)),
    ],
    'apple' => const [
      ('Black Titanium', Color(0xFF1F2937)),
      ('Natural Titanium', Color(0xFFB4AB9E)),
      ('Desert Titanium', Color(0xFFD2AB7F)),
      ('Ultramarine', Color(0xFF2563EB)),
    ],
    'oneplus' => const [
      ('Black Eclipse', Color(0xFF111827)),
      ('Arctic Dawn', Color(0xFFE2E8F0)),
      ('Crimson Red', Color(0xFFDC2626)),
      ('Nord Blue', Color(0xFF3B82F6)),
    ],
    'redmi' => const [
      ('Midnight Black', Color(0xFF111827)),
      ('Coral Green', Color(0xFF14B8A6)),
      ('Lavender Purple', Color(0xFFA78BFA)),
      ('Sunrise Gold', Color(0xFFFBBF24)),
    ],
    'vivo' => const [
      ('Starry Blue', Color(0xFF2563EB)),
      ('Moonlight White', Color(0xFFF1F5F9)),
      ('Emerald Green', Color(0xFF10B981)),
      ('Velvet Black', Color(0xFF0F172A)),
    ],
    'oppo' => const [
      ('Ocean Blue', Color(0xFF0E7490)),
      ('Silky Gold', Color(0xFFF59E0B)),
      ('Midnight Black', Color(0xFF111827)),
      ('Mint Green', Color(0xFF86EFAC)),
    ],
    'realme' => const [
      ('Speed Green', Color(0xFF22C55E)),
      ('Sunrise Beige', Color(0xFFFBBF24)),
      ('Steel Black', Color(0xFF1F2937)),
      ('Purple Mist', Color(0xFFA855F7)),
    ],
    'motorola' => const [
      ('Vegan Blue', Color(0xFF1E40AF)),
      ('Peach Fuzz', Color(0xFFFB923C)),
      ('Forest Grey', Color(0xFF4B5563)),
      ('Marshmallow', Color(0xFFF3F4F6)),
    ],
    'nothing' => const [
      ('Black', Color(0xFF111827)),
      ('White', Color(0xFFF5F5F5)),
      ('Blue', Color(0xFF2563EB)),
      ('Orange', Color(0xFFF97316)),
    ],
    'googlepixel' => const [
      ('Obsidian', Color(0xFF111827)),
      ('Porcelain', Color(0xFFF1F5F9)),
      ('Bay Blue', Color(0xFF2563EB)),
      ('Aloe Green', Color(0xFF4ADE80)),
    ],
    'iqoo' => const [
      ('Legend White', Color(0xFFF5F5F5)),
      ('Alpha Black', Color(0xFF111827)),
      ('Flame Orange', Color(0xFFF97316)),
      ('Track Blue', Color(0xFF3B82F6)),
    ],
    'poco' => const [
      ('Power Black', Color(0xFF111827)),
      ('Cyber Yellow', Color(0xFFFACC15)),
      ('Frost Blue', Color(0xFF60A5FA)),
      ('Lime Green', Color(0xFF84CC16)),
    ],
    'lava' => const [
      ('Glass Blue', Color(0xFF2563EB)),
      ('Prism Gold', Color(0xFFF59E0B)),
      ('Shadow Black', Color(0xFF111827)),
      ('Crimson', Color(0xFFDC2626)),
    ],
    'infinix' => const [
      ('Cyber Green', Color(0xFF22C55E)),
      ('Racing Grey', Color(0xFF4B5563)),
      ('Halo White', Color(0xFFF1F5F9)),
      ('Mirage Purple', Color(0xFF9333EA)),
    ],
    'tecno' => const [
      ('Meteor Blue', Color(0xFF2563EB)),
      ('Comet Green', Color(0xFF14B8A6)),
      ('Orbit Black', Color(0xFF111827)),
      ('Moonlight Silver', Color(0xFFCBD5E1)),
    ],
    'nokia' => const [
      ('Nordic Blue', Color(0xFF1E40AF)),
      ('Charcoal', Color(0xFF1F2937)),
      ('Cloud Grey', Color(0xFF9CA3AF)),
      ('Sand', Color(0xFFD97706)),
    ],
    'honor' => const [
      ('Emerald Green', Color(0xFF10B981)),
      ('Midnight Black', Color(0xFF111827)),
      ('Ocean Cyan', Color(0xFF06B6D4)),
      ('Titanium Silver', Color(0xFFCBD5E1)),
    ],
    _ => const [
      ('Black', Color(0xFF111827)),
      ('Blue', Color(0xFF3B82F6)),
      ('Green', Color(0xFF22C55E)),
      ('Silver', Color(0xFFE5E7EB)),
    ],
  };

  return colors
      .map(
        (color) => _BncMobileColorOption(
          name: color.$1,
          asset: _mobileModelColorAsset(model, color.$1),
          swatch: color.$2,
        ),
      )
      .toList();
}

String _mobileModelImageAsset(String brandName, String modelName) {
  final brandKey = _normalizeKey(brandName);
  final modelKey = _normalizeKey(modelName);

  final realAsset = _mobileModelRealAsset(brandName, modelName);
  if (realAsset != null) return realAsset;

  if (brandKey == 'samsung' && modelName.contains('S25+')) {
    return '$_mockupPath/mobile-model-samsung-galaxys255g-navy.png';
  }
  if (brandKey == 'samsung' && modelName == 'Galaxy S25 5G') {
    return '$_mockupPath/mobile-model-samsung-galaxys255g-mint.png';
  }

  return '$_mockupPath/mobile-model-$brandKey-$modelKey.png';
}

