      brandKey == 'realme' ||
      brandKey == 'redmi' ||
      brandKey == 'iqoo' ||
      brandKey == 'poco') {
    final basePrice = _mobilePriceNumber(model.price);
    final baseOldPrice = _mobilePriceNumber(model.oldPrice);
    final hasTwelveGb =
        model.storage.contains('12 GB') ||
        model.storage.contains('16 GB') ||
        basePrice > 45000;
    return [
      _BncMobileVariantOption(
        storage: model.storage,
        price: _formatMobilePrice(basePrice),
        oldPrice: _formatMobilePrice(baseOldPrice),
        discount: model.discount,
      ),
      _BncMobileVariantOption(
        storage: hasTwelveGb ? '12 GB / 512 GB' : '8 GB / 256 GB',
        price: _formatMobilePrice(basePrice + (hasTwelveGb ? 12000 : 4000)),
        oldPrice: _formatMobilePrice(
          baseOldPrice + (hasTwelveGb ? 15000 : 5000),
        ),
        discount: model.discount,
      ),
      _BncMobileVariantOption(
        storage: hasTwelveGb ? '16 GB / 512 GB' : '12 GB / 256 GB',
        price: _formatMobilePrice(basePrice + (hasTwelveGb ? 18000 : 8000)),
        oldPrice: _formatMobilePrice(
          baseOldPrice + (hasTwelveGb ? 22000 : 10000),
        ),
        discount: model.discount,
      ),
    ];
  }
  if (brandKey == 'motorola' ||
      brandKey == 'nothing' ||
      brandKey == 'lava' ||
      brandKey == 'infinix' ||
      brandKey == 'tecno' ||
      brandKey == 'nokia' ||
      brandKey == 'honor') {
    final basePrice = _mobilePriceNumber(model.price);
    final baseOldPrice = _mobilePriceNumber(model.oldPrice);
    return [
      _BncMobileVariantOption(
        storage: model.storage,
        price: _formatMobilePrice(basePrice),
        oldPrice: _formatMobilePrice(baseOldPrice),
        discount: model.discount,
      ),
      _BncMobileVariantOption(
        storage: '8 GB / 256 GB',
        price: _formatMobilePrice(basePrice + 5000),
        oldPrice: _formatMobilePrice(baseOldPrice + 6000),
        discount: model.discount,
      ),
    ];
  }
  final price = _mobilePriceNumber(model.price);
  final oldPrice = _mobilePriceNumber(model.oldPrice);
  final hasHighStorage =
      model.storage.contains('256') ||
      model.storage.contains('512') ||
      model.brand.toLowerCase().contains('apple');
  final baseStorage = model.storage.contains('/')
      ? model.storage.split('/').last.trim()
      : model.storage;
  final higherStorage = hasHighStorage ? '512 GB' : '256 GB';
  return [
    _BncMobileVariantOption(
      storage: baseStorage,
      price: _formatMobilePrice(price),
      oldPrice: _formatMobilePrice(oldPrice),
      discount: model.discount,
    ),
    _BncMobileVariantOption(
      storage: higherStorage,
      price: _formatMobilePrice(price + (hasHighStorage ? 20000 : 8000)),
      oldPrice: _formatMobilePrice(oldPrice + (hasHighStorage ? 23000 : 10000)),
      discount: model.discount,
    ),
  ];
}

int _mobilePriceNumber(String price) {
  final digits = price.replaceAll(RegExp(r'[^0-9]'), '');
  return int.tryParse(digits) ?? 0;
}

String _formatMobilePrice(int price) {
  final text = price.toString();
  final buffer = StringBuffer();
  for (var i = 0; i < text.length; i++) {
    final fromRight = text.length - i;
    buffer.write(text[i]);
    if (fromRight > 1 && fromRight % 2 == 0 && i != text.length - 1) {
      buffer.write(',');
    }
  }
  return 'Rs$buffer';
}

bool _isMobileAccessoriesRoute(String categoryName, String title) {
  final routeKey = _normalizeKey('$categoryName $title');
  return routeKey.contains('mobile') && routeKey.contains('accessor');
}

bool _isMobileRepairRoute(String categoryName, String title) {
  final routeKey = _normalizeKey('$categoryName $title');
  return routeKey.contains('mobile') &&
      (routeKey.contains('repair') ||
          routeKey.contains('screenreplacement') ||
          routeKey.contains('batteryreplacement') ||
          routeKey.contains('chargingport') ||
          routeKey.contains('waterdamage') ||
          routeKey.contains('softwaredata') ||
          routeKey.contains('dataservice'));
}

bool _isElectronicsRepairRoute(String categoryName, String title) {
  final routeKey = _normalizeKey('$categoryName $title');
  return routeKey.contains('electronics') &&
      (routeKey.contains('repair') ||
          routeKey.contains('service') ||
          routeKey.contains('display') ||
          routeKey.contains('battery') ||
          routeKey.contains('keyboard') ||
          routeKey.contains('software') ||
          routeKey.contains('data') ||
          routeKey.contains('applianceservice') ||
          routeKey.contains('tvandac'));
}

