    'Connectors': 'OTG and USB adapters for storage and accessories.',
    'Storage': 'Memory cards and phone storage add-ons.',
    'Care': 'Cleaning kits and daily phone maintenance items.',
  };
  const shortByCategory = {
    'Chargers': 'Adapters',
    'Cables': 'Type-C / Lightning',
    'Screen guards': 'Glass',
    'Cases': 'Covers',
    'Audio': 'Earbuds',
    'Power banks': 'Backup',
    'Mounts': 'Car use',
    'Protection': 'Lens',
    'Connectors': 'OTG',
    'Storage': 'Cards',
    'Care': 'Cleaning',
  };
  const assetByCategory = {
    'Chargers': '$_mockupPath/acc-category-chargers.png',
    'Cables': '$_mockupPath/acc-category-cables.png',
    'Screen guards': '$_mockupPath/acc-category-screen-guards.png',
    'Cases': '$_mockupPath/acc-category-cases.png',
    'Audio': '$_mockupPath/acc-category-audio.png',
    'Power banks': '$_mockupPath/acc-category-power-banks.png',
    'Mounts': '$_mockupPath/acc-category-mounts.png',
    'Protection': '$_mockupPath/acc-category-protection.png',
    'Connectors': '$_mockupPath/acc-category-connectors.png',
    'Storage': '$_mockupPath/acc-category-storage.png',
    'Care': '$_mockupPath/acc-category-care.png',
  };

  final categories = <String, _BncMobileAccessorySpec>{};
  for (final accessory in accessories) {
    categories.putIfAbsent(accessory.category, () => accessory);
  }

  return categories.entries.map((entry) {
    final first = entry.value;
    return _BncMobileAccessoryCategorySpec(
      name: entry.key,
      detail: detailByCategory[entry.key] ?? first.detail,
      shortLabel: shortByCategory[entry.key] ?? '${entry.key} items',
      asset: assetByCategory[entry.key] ?? first.asset,
      icon: first.icon,
    );
  }).toList();
}

