String _shopNameForCategory(String categoryName, List<_BncShopSpec> shops) {
  if (shops.isNotEmpty) {
    return shops.first.name;
  }

  final key = _normalizeKey(categoryName);
  if (key.contains('grocery')) return 'Fresh Basket';
  if (key.contains('restaurant')) return 'Spice Garden';
  if (key.contains('beauty')) return 'Maya Beauty Salon';
  if (key.contains('pharmacy')) return 'City Care Pharmacy';
  if (key.contains('electronics') || key.contains('mobile'))
    return 'Tech World';
  if (key.contains('home')) return 'HomeFix Pro';
  return 'BNC verified shop';
}

