  @override
  State<_HorizontalOfferImageScroller> createState() =>
      _HorizontalOfferImageScrollerState();
}

class _HorizontalOfferImageScrollerState
    extends State<_HorizontalOfferImageScroller> {
  late final PageController _pageController;
  Timer? _autoScrollTimer;
  int _currentPage = 0;

  @override
  void initState() {
    super.initState();
    _pageController = PageController(viewportFraction: 0.82);
    _startAutoScroll();
  }

  @override
  void didUpdateWidget(covariant _HorizontalOfferImageScroller oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.offers.length != widget.offers.length) {
      _currentPage = 0;
      _startAutoScroll();
    }
  }

  @override
  void dispose() {
    _autoScrollTimer?.cancel();
    _pageController.dispose();
    super.dispose();
  }

  void _startAutoScroll() {
    _autoScrollTimer?.cancel();
    _autoScrollTimer = null;

    if (widget.offers.length < 2) {
      return;
    }

    _autoScrollTimer = Timer.periodic(const Duration(seconds: 3), (_) {
      if (!mounted || !_pageController.hasClients) {
        return;
      }

      final nextPage = (_currentPage + 1) % widget.offers.length;
      _pageController.animateToPage(
        nextPage,
        duration: const Duration(milliseconds: 520),
        curve: Curves.easeOutCubic,
      );
    });
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      height: 156,
      child: PageView.builder(
        controller: _pageController,
        physics: const BouncingScrollPhysics(),
        padEnds: false,
        itemCount: widget.offers.length,
        onPageChanged: (index) {
          _currentPage = index;
        },
        itemBuilder: (context, index) {
          final offer = widget.offers[index];
          return Padding(
            padding: EdgeInsets.only(
              right: index == widget.offers.length - 1 ? 0 : 12,
            ),
            child: _CategoryOfferSlideCard(
              offer: offer,
              onTap: () {
                _openCategoryOffer(
                  context,
                  offer,
                  shops: widget.shops,
                  catalogService: widget.catalogService,
                );
              },
            ),
          );
        },
      ),
    );
  }
}

