class _ProductDealsHorizontalScroller extends StatelessWidget {
  const _ProductDealsHorizontalScroller({
    required this.item,
    required this.categoryName,
    required this.shops,
    this.deals,
    this.catalogService,
  });

  final _CategoryServiceSpec item;
  final String categoryName;
  final List<_BncProductDealSpec>? deals;
  final List<_BncShopSpec> shops;
  final CatalogService? catalogService;

  @override
  Widget build(BuildContext context) {
    final productDeals = deals ?? _productDealsForCategory(categoryName, item);

    return SizedBox(
      height: 206,
      child: ListView.separated(
        scrollDirection: Axis.horizontal,
        physics: const BouncingScrollPhysics(),
        itemCount: productDeals.length,
        separatorBuilder: (_, __) => const SizedBox(width: 12),
        itemBuilder: (context, index) {
          final deal = productDeals[index];
          return _ProductDealSlideCard(
            deal: deal,
            onTap: () {
              final sourceItemTitle = deal.sourceItemTitle ?? item.title;
              final itemKey = _normalizeKey(sourceItemTitle);
              final isRestaurantItem =
                  _isRestaurantTopLevelKey(itemKey) ||
                  _isRestaurantFoodGroupKey(itemKey) ||
                  _isRestaurantFoodProductKey(
                    _normalizeKey(deal.subcategoryName),
                  );

              if (isRestaurantItem) {
                _openSubcategoryShopList(
                  context,
                  categoryName: categoryName,
                  subcategoryName: deal.subcategoryName,
                  imageAsset: deal.asset,
                  shops: shops,
                  catalogService: catalogService,
                );
                return;
              }

              if (_opensDirectProductSubcategories(
                sourceItemTitle,
                deal.subcategoryName,
              )) {
                _openSubcategoryProductsDirect(
                  context,
                  categoryName: categoryName,
                  subcategoryName: deal.subcategoryName,
                  imageAsset: deal.asset,
                  shops: shops,
                  catalogService: catalogService,
                );
                return;
              }

              _openSubcategoryShopList(
                context,
                categoryName: categoryName,
                subcategoryName: deal.subcategoryName,
                imageAsset: deal.asset,
                shops: shops,
                catalogService: catalogService,
              );
            },
          );
        },
      ),
    );
  }
}

