class _BncProductDealSpec {
  const _BncProductDealSpec({
    required this.title,
    required this.discount,
    required this.code,
    required this.asset,
    required this.subcategoryName,
    this.sourceItemTitle,
  });

  final String title;
  final String discount;
  final String code;
  final String asset;
  final String subcategoryName;
  final String? sourceItemTitle;

  _BncProductDealSpec withSourceItem(String itemTitle) {
    return _BncProductDealSpec(
      title: title,
      discount: discount,
      code: code,
      asset: asset,
      subcategoryName: subcategoryName,
      sourceItemTitle: itemTitle,
    );
  }
}

List<String> _shopCameraPhotosForProduct(String asset) {
  return [asset];
}

