  String categoryName,
  _CategoryServiceSpec item,
) {
  final key = _normalizeKey(categoryName);
  final itemKey = _normalizeKey(item.title);
  if (itemKey.contains('keralameals')) {
    return _productsForSubcategory('Kerala Meals', 'Kerala Meals')
        .map(
          (meal) => _BncProductDealSpec(
            title: meal,
            discount: _discountForProductName(meal),
            code: 'Today',
            asset: _productImageFor(
              meal,
              'Kerala Meals',
              'Kerala Meals',
              item.asset,
