  if (key.contains('electronics') &&
      (itemKey.contains('laptop') ||
          itemKey.contains('computer') ||
          itemKey.contains('electronicappliance') ||
          itemKey.contains('accessoriesperipheral') ||
          itemKey.contains('accessor') ||
          itemKey.contains('repairservice') ||
          itemKey.contains('repairservices'))) {
    return _productsForSubcategory('Electronics', item.title)
        .map(
          (product) => _BncProductDealSpec(
            title: product,
            discount: _discountForProductName(product),
            code: item.badge,
            asset: _productImageFor(
              product,
              'Electronics',
              item.title,
              item.asset,
            ),
            subcategoryName: product,
          ),
        )
        .toList();
  }

  if (item.tags.isNotEmpty) {
    return item.tags.map((tag) {
      return _BncProductDealSpec(
        title: tag,
        discount: _discountForProductDeal(tag, categoryName),
        code: 'Today',
        asset: _subcategoryRealImageFor(tag, categoryName, item.asset),
        subcategoryName: tag,
      );
    }).toList();
  }

  final offers = _latestOffersForCategory(categoryName, item.title);
  if (offers.isNotEmpty) {
    return offers.map((offer) {
      return _BncProductDealSpec(
        title: offer.title,
        discount: offer.code,
        code: 'Offer',
        asset: offer.asset,
        subcategoryName: offer.title,
      );
    }).toList();
  }

  return const [];
}

List<_BncProductDealSpec> _bestProductDealsForCategory(
  String categoryName,
  List<_CategoryServiceSpec> items,
) {
  if (items.isEmpty) return const [];

  final seen = <String>{};
  final deals = <_BncProductDealSpec>[];
  for (final item in items) {
    for (final deal in _productDealsForCategory(categoryName, item)) {
      final dealKey = _normalizeKey('${deal.title}-${deal.code}-${deal.asset}');
      if (seen.add(dealKey)) {
        deals.add(deal.withSourceItem(item.title));
      }
    }
  }
  return deals;
}

bool _isKeralaMealOffer(_BncOfferSpec offer) {
  final shopKey = _normalizeKey(offer.shop);
  final offerKey = _normalizeKey('${offer.title} ${offer.code}');
  return shopKey.contains('spicegarden') &&
      (offerKey.contains('meal') ||
          offerKey.contains('meals') ||
          offerKey.contains('fish20') ||
          offerKey.contains('vegmeal'));
}

void _openKeralaMealRestaurants(
  BuildContext context, {
  required String mealName,
  required String imageAsset,
  List<_BncShopSpec> shops = const [],
  CatalogService? catalogService,
}) {
  final matchedShops = _shopsForSubcategory('Kerala Meals', mealName, shops);
  final fallbackShop = _allBncShops.firstWhere(
    (shop) => shop.name == 'Spice Garden',
  );

  _openSubcategoryShopList(
    context,
    categoryName: 'Kerala Meals',
    subcategoryName: mealName,
    imageAsset: imageAsset,
    shops: matchedShops.isNotEmpty ? matchedShops : [fallbackShop],
    catalogService: catalogService,
  );
}

void _openCategoryOffer(
  BuildContext context,
  _BncOfferSpec offer, {
  List<_BncShopSpec> shops = const [],
  CatalogService? catalogService,
}) {
  if (_isKeralaMealOffer(offer)) {
    _openKeralaMealRestaurants(
      context,
      mealName: offer.title,
      imageAsset: offer.asset,
      shops: shops,
      catalogService: catalogService,
    );
    return;
  }

  Navigator.of(context).push(
    MaterialPageRoute<void>(
      builder: (_) => BncDealsPage(initialCode: offer.code),
    ),
  );
}

String _discountForProductDeal(String title, String categoryName) {
  final key = _normalizeKey('$title $categoryName');
  if (key.contains('leafy') || key.contains('vegetable')) {
    return '10% OFF';
  }
  if (key.contains('fruit')) {
    return '15% OFF';
  }
  if (key.contains('fish')) {
    return '20% OFF';
  }
  if (key.contains('meat') ||
      key.contains('chicken') ||
      key.contains('mutton')) {
    return '12% OFF';
  }
  if (key.contains('monthly') || key.contains('essential')) {
    return 'SAVE 8%';
  }
  if (key.contains('care') || key.contains('beauty')) {
    return 'SAVE 10';
  }
  return 'OFFER';
}

