void _openSubcategoryProductsDirect(
  BuildContext context, {
  required String categoryName,
  required String subcategoryName,
  required String imageAsset,
  required List<_BncShopSpec> shops,
  CatalogService? catalogService,
}) {
  final matchedShops = _shopsForSubcategory(
    categoryName,
    subcategoryName,
    shops,
  );
  final fallbackShops = shops.isNotEmpty ? shops : _allBncShops;
  final shop = matchedShops.isNotEmpty
      ? matchedShops.first
      : fallbackShops.isNotEmpty
      ? fallbackShops.first
      : null;

  if (shop == null) {
    _openSubcategoryShopList(
      context,
      categoryName: categoryName,
      subcategoryName: subcategoryName,
      imageAsset: imageAsset,
      shops: shops,
      catalogService: catalogService,
    );
    return;
  }

  Navigator.of(context).push(
    MaterialPageRoute<void>(
      builder: (_) => _BncSubcategoryProductGridPage(
        shop: shop,
        shops: matchedShops.isNotEmpty ? matchedShops : fallbackShops,
        categoryName: categoryName,
        subcategoryName: subcategoryName,
        imageAsset: imageAsset,
        catalogService: catalogService,
      ),
    ),
  );
}

List<_BncShopSpec> _shopsForSubcategory(
  String categoryName,
  String subcategoryName,
  List<_BncShopSpec> shops,
) {
  final source = shops.isEmpty ? _allBncShops : shops;
  final categoryKey = _normalizeKey(categoryName);
  final subcategoryKey = _normalizeKey(subcategoryName);
  final providerNames = _providerShopNamesForSubcategory(subcategoryKey);

  if (providerNames.isNotEmpty) {
    final providerMatches = source.where((shop) {
      return providerNames.contains(_normalizeKey(shop.name));
    }).toList();

    if (providerMatches.isNotEmpty) {
      return _shopsNearestFirst(providerMatches);
    }
  }

  final matches = source.where((shop) {
    final shopKey = _normalizeKey(
      '${shop.name} ${shop.category} ${shop.badge}',
    );
    return shopKey.contains(categoryKey) ||
        categoryKey.contains(_normalizeKey(shop.category)) ||
        shopKey.contains(subcategoryKey);
  }).toList();

  if (matches.isNotEmpty) {
    return _shopsNearestFirst(matches);
  }

  final relatedMatches = source.where((shop) {
    final shopCategory = _normalizeKey(shop.category);
    return _relatedCategoryKeys(categoryKey).any(shopCategory.contains);
  }).toList();
  return _shopsNearestFirst(relatedMatches);
}

List<_BncShopSpec> _shopsNearestFirst(List<_BncShopSpec> shops) {
  return [...shops]..sort(
    (left, right) => _distanceValue(left).compareTo(_distanceValue(right)),
  );
}

List<String> _providerShopNamesForSubcategory(String subcategoryKey) {
  if (subcategoryKey.contains('leafygreens') ||
      subcategoryKey.contains('leafyvegetables') ||
      subcategoryKey.contains('spinach') ||
      subcategoryKey.contains('coriander') ||
      subcategoryKey.contains('mint') ||
      subcategoryKey.contains('potato') ||
      subcategoryKey.contains('onion') ||
      subcategoryKey.contains('carrot') ||
      subcategoryKey.contains('cabbage') ||
