  }
  if (subcategoryKey.contains('dailystock') ||
      subcategoryKey.contains('homepacks') ||
      subcategoryKey.contains('monthlyessentials') ||
      subcategoryKey.contains('rice') ||
      subcategoryKey.contains('dal') ||
