      subcategoryKey.contains('snacks')) {
    return const ['quickmart', 'freshbasket'];
  }
  if (subcategoryKey.contains('gift') ||
      subcategoryKey.contains('hamper') ||
      subcategoryKey.contains('festival') ||
      subcategoryKey.contains('dryfruit') ||
      subcategoryKey.contains('chocolate') ||
      subcategoryKey.contains('greeting') ||
      subcategoryKey.contains('stationery')) {
    return const ['freshbasket', 'quickmart'];
  }
  if (_isRestaurantFoodGroupKey(subcategoryKey)) {
    return const ['alukkyhotel', 'spicegarden'];
  }
  if (subcategoryKey.contains('jewellery') ||
      subcategoryKey.contains('jewelry') ||
      subcategoryKey.contains('chain') ||
      subcategoryKey.contains('bracelet') ||
      subcategoryKey.contains('pendant') ||
      subcategoryKey.contains('gold') ||
      subcategoryKey.contains('silver') ||
      subcategoryKey.contains('leatherbracelet') ||
      subcategoryKey.contains('necklace') ||
