  if (_isAccessoryVariantGroupKey(subcategoryKey) ||
      _isAccessoryProductKey(subcategoryKey)) {
    return const ['timezonewatches', 'lensopticals', 'starjewelers'];
  }
  if (subcategoryKey.contains('footwear') ||
      subcategoryKey.contains('shoe') ||
      subcategoryKey.contains('sandal') ||
