      subcategoryKey.contains('cameralensrepair') ||
      subcategoryKey.contains('softwareservice') ||
      subcategoryKey.contains('dataservice')) {
    return const ['hangamobiles', 'citymobilehub'];
  }
  return const [];
}

List<String> _relatedCategoryKeys(String categoryKey) {
  if (categoryKey.contains('grocery')) {
    return const ['grocery', 'mart', 'basket', 'fresh'];
  }
  if (categoryKey.contains('restaurant')) {
    return const ['restaurant', 'cafe', 'hotel', 'food'];
  }
  if (categoryKey.contains('beauty')) {
    return const ['beauty', 'salon', 'spa'];
  }
  if (categoryKey.contains('tailor')) {
    return const ['tailor', 'fashion'];
  }
  if (categoryKey.contains('mobile')) {
    return const ['mobile', 'phone'];
  }
  if (categoryKey.contains('electronics')) {
    return const ['electronics', 'tech', 'computer', 'laptop'];
  }
  if (categoryKey.contains('pharmacy')) {
    return const ['pharmacy', 'medical', 'care'];
  }
  if (categoryKey.contains('home')) {
    return const ['home', 'service', 'fix'];
  }
  if (categoryKey.contains('bakery')) {
    return const ['bakery', 'sweet'];
  }
  return [categoryKey];
}

