class _BncSubcategoryShopProductsPage extends StatelessWidget {
  const _BncSubcategoryShopProductsPage({
    required this.shop,
    required this.categoryName,
    required this.subcategoryName,
    required this.imageAsset,
    this.catalogService,
  });

  final _BncShopSpec shop;
  final String categoryName;
  final String subcategoryName;
  final String imageAsset;
  final CatalogService? catalogService;

  @override
  Widget build(BuildContext context) {
    if (_isMobileRepairRoute(categoryName, subcategoryName)) {
      return _BncMobileRepairEnquiryPage(
        shop: shop,
        serviceName: subcategoryName,
        imageAsset: imageAsset,
      );
    }
    if (_isElectronicsRepairRoute(categoryName, subcategoryName)) {
      return _BncMobileRepairEnquiryPage(
        shop: shop,
        serviceName: subcategoryName,
        imageAsset: imageAsset,
        title: 'Service enquiry',
        modelLabel: 'Device / model',
        serviceContextLabel: 'Service center',
        actionLabel: 'Request service center visit',
      );
    }

    final products = _productsForSubcategory(categoryName, subcategoryName);
    final productCards = products
        .map(
          (product) => _BncProductSaleSpec(
            name: product,
            asset: _productImageFor(
              product,
              categoryName,
              subcategoryName,
              imageAsset,
            ),
            shopName: shop.name,
            discount: _discountForProductName(product),
            oldPrice: _oldPriceForProductName(product),
            price: _priceForProductName(product),
            variants: _variantsForProductName(product),
            subcategoryName: product,
            badge: _badgeForProductName(product),
          ),
        )
        .toList();
    final subcategoryKey = _normalizeKey(subcategoryName);
    _BncProductSaleSpec? matchingProduct;
    for (final product in productCards) {
      if (_normalizeKey(product.name) == subcategoryKey ||
          _normalizeKey(product.subcategoryName) == subcategoryKey) {
        matchingProduct = product;
        break;
      }
    }
    final selectedProduct =
        matchingProduct ??
        _BncProductSaleSpec(
          name: subcategoryName,
          asset: imageAsset,
          shopName: shop.name,
          discount: _discountForProductName(subcategoryName),
          oldPrice: _oldPriceForProductName(subcategoryName),
          price: _priceForProductName(subcategoryName),
          variants: _variantsForProductName(subcategoryName),
          subcategoryName: subcategoryName,
          badge: _badgeForProductName(subcategoryName),
        );
    final selectedKey = _normalizeKey(selectedProduct.name);
    final categoryKey = _normalizeKey(categoryName);
    final isRestaurantFoodPage =
        _isRestaurantTopLevelKey(categoryKey) ||
        _isRestaurantTopLevelKey(subcategoryKey) ||
        _isRestaurantFoodGroupKey(subcategoryKey) ||
        _isRestaurantFoodProductKey(subcategoryKey);
    final moreProducts = productCards
        .where((product) => _normalizeKey(product.name) != selectedKey)
        .toList();
    final shopAvailableProducts = isRestaurantFoodPage
        ? productCards
        : moreProducts;
    final showProductList =
        _showsDetailedSubcategoryList(categoryName, subcategoryName) &&
        productCards.length > 1;

    return _BncPhoneSizedRoute(
      child: Scaffold(
        backgroundColor: Colors.white,
        body: SafeArea(
          child: CustomScrollView(
            physics: const BouncingScrollPhysics(),
            slivers: [
              SliverToBoxAdapter(
                child: Container(
                  color: const Color(0xFFEAF3FF),
                  padding: const EdgeInsets.fromLTRB(6, 8, 8, 10),
