                  delegate: SliverChildBuilderDelegate((context, index) {
                    final product = shopAvailableProducts[index];
                    return _BncProductSaleCard(
                      product: product,
                      onTap: () => Navigator.of(context).push(
                        MaterialPageRoute<void>(
                          builder: (_) => _BncSubcategoryShopProductsPage(
                            shop: shop,
                            categoryName: categoryName,
                            subcategoryName: product.name,
                            imageAsset: product.asset,
                            catalogService: catalogService,
                          ),
                        ),
                      ),
                    );
                  }, childCount: shopAvailableProducts.length),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

