class _BncRepairTextField extends StatelessWidget {
  const _BncRepairTextField({
    required this.controller,
    required this.label,
    required this.icon,
    this.keyboardType,
    this.maxLines = 1,
  });

  final TextEditingController controller;
  final String label;
  final IconData icon;
  final TextInputType? keyboardType;
  final int maxLines;

  @override
  Widget build(BuildContext context) {
    return TextField(
      controller: controller,
      keyboardType: keyboardType,
      maxLines: maxLines,
      decoration: InputDecoration(
        labelText: label,
        prefixIcon: Icon(icon, color: brandNavy),
        filled: true,
        fillColor: Colors.white,
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(18),
          borderSide: const BorderSide(color: brandLine),
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(18),
          borderSide: const BorderSide(color: brandLine),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(18),
          borderSide: const BorderSide(color: brandNavy, width: 1.4),
        ),
      ),
    );
  }
}

class _BncRepairTimeSelector extends StatelessWidget {
  const _BncRepairTimeSelector({
    required this.selected,
    required this.onChanged,
  });

  final String selected;
  final ValueChanged<String> onChanged;

  @override
  Widget build(BuildContext context) {
    const options = ['Today', 'Tomorrow', 'This week'];
    return Wrap(
      spacing: 8,
      runSpacing: 8,
      children: options.map((option) {
        final active = option == selected;
        return ChoiceChip(
          selected: active,
          label: Text(option),
          onSelected: (_) => onChanged(option),
          selectedColor: brandGold,
          backgroundColor: Colors.white,
          side: BorderSide(color: active ? brandGold : brandLine),
          labelStyle: TextStyle(
            color: active ? brandNavy : brandMuted,
            fontSize: 12,
            fontWeight: FontWeight.w900,
          ),
        );
      }).toList(),
    );
  }
}

class _BncSelectedShopProductCard extends StatefulWidget {
  const _BncSelectedShopProductCard({
    required this.product,
    required this.shop,
    required this.categoryName,
    required this.onOpenShop,
  });

  final _BncProductSaleSpec product;
  final _BncShopSpec shop;
  final String categoryName;
