  @override
  State<_BncSelectedShopProductCard> createState() =>
      _BncSelectedShopProductCardState();
}

class _BncSelectedShopProductCardState
    extends State<_BncSelectedShopProductCard> {
  late String _selectedUnit;
  int _quantity = 1;

  @override
  void initState() {
    super.initState();
    _selectedUnit = _unitOptionsForProductName(widget.product.name).first;
  }

  @override
  void didUpdateWidget(covariant _BncSelectedShopProductCard oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.product.name != widget.product.name) {
      _selectedUnit = _unitOptionsForProductName(widget.product.name).first;
      _quantity = 1;
    }
  }

  @override
  Widget build(BuildContext context) {
    final product = widget.product;
    final shop = widget.shop;
    final onOpenShop = widget.onOpenShop;
    final usesWeightControls = _usesProductWeightControls(widget.categoryName);
    final productKey = _normalizeKey(product.name);
    final usesFreeSizeOption = _usesFreeSizeFashionOption(productKey);
    final usesFashionSizes = _usesFashionSizeOptions(productKey);
    final usesFoodPortions = _isRestaurantFoodProductKey(productKey);
    final usesAccessoryStyles = _isAccessoryProductKey(productKey);
    final usesScaledQuantity = usesWeightControls || usesFoodPortions;
    final selectedPrice = usesScaledQuantity
        ? _priceForQuantity(
            _priceForSelectedUnit(
              product.price,
              product.variants,
              _selectedUnit,
            ),
            _quantity,
          )
        : product.price;
    final selectedOldPrice = usesScaledQuantity
        ? _priceForQuantity(
            _priceForSelectedUnit(
              product.oldPrice,
              product.variants,
              _selectedUnit,
            ),
            _quantity,
          )
        : product.oldPrice;
    final shareUnit =
        usesScaledQuantity ||
            usesFashionSizes ||
            usesFreeSizeOption ||
            usesAccessoryStyles
        ? '$_quantity x $_selectedUnit'
        : product.subcategoryName;
    return Container(
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(26),
        border: Border.all(color: brandLine),
        boxShadow: const [
          BoxShadow(
            color: Color(0x1408204A),
            blurRadius: 22,
            offset: Offset(0, 10),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(12, 12, 12, 0),
            child: Container(
              height: 196,
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(24),
                boxShadow: const [
                  BoxShadow(
                    color: Color(0x2208204A),
                    blurRadius: 18,
                    offset: Offset(0, 8),
                  ),
                ],
              ),
              child: ClipRRect(
                borderRadius: BorderRadius.circular(24),
                child: Stack(
                  fit: StackFit.expand,
                  children: [
                    Image.asset(
                      product.asset,
                      fit: BoxFit.cover,
                      errorBuilder: (_, __, ___) => Container(
                        color: const Color(0xFFEAF1FF),
                        child: const Icon(
                          Icons.shopping_bag_outlined,
                          color: brandNavy,
                          size: 42,
                        ),
                      ),
                    ),
                    Positioned.fill(
                      child: DecoratedBox(
                        decoration: BoxDecoration(
                          gradient: LinearGradient(
                            colors: [
                              Colors.black.withValues(alpha: 0.04),
                              Colors.black.withValues(alpha: 0.28),
                            ],
                            begin: Alignment.topCenter,
                            end: Alignment.bottomCenter,
                          ),
                        ),
                      ),
                    ),
                    Positioned(
                      top: 12,
                      left: 12,
                      child: _BncProductDiscountBadge(label: product.discount),
                    ),
                    Positioned(
                      top: 12,
                      right: 12,
                      child: Column(
                        children: [
                          Container(
                            width: 44,
                            height: 44,
                            decoration: BoxDecoration(
                              color: Colors.white.withValues(alpha: 0.96),
                              shape: BoxShape.circle,
                              boxShadow: const [
                                BoxShadow(
                                  color: Color(0x2208204A),
                                  blurRadius: 12,
                                  offset: Offset(0, 5),
                                ),
                              ],
                            ),
                            child: const Icon(
                              Icons.favorite_border_rounded,
                              color: brandNavy,
