class _BncApparelSizeSelector extends StatelessWidget {
  const _BncApparelSizeSelector({
    required this.selectedSize,
    required this.sizes,
    required this.onSelected,
  });

  final String selectedSize;
  final List<String> sizes;
  final ValueChanged<String> onSelected;

  @override
  Widget build(BuildContext context) {
    final hasOnlyFreeSize = sizes.length == 1 && sizes.first == 'Free size';
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          hasOnlyFreeSize ? 'Select option' : 'Select size',
          style: TextStyle(
            color: brandNavy,
            fontSize: 14,
            fontWeight: FontWeight.w900,
          ),
        ),
        const SizedBox(height: 9),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: sizes.map((size) {
            final selected = size == selectedSize;
            return ChoiceChip(
              selected: selected,
              label: Text(size),
              onSelected: (_) => onSelected(size),
              selectedColor: brandNavy,
              backgroundColor: Colors.white,
              side: BorderSide(color: selected ? brandNavy : brandLine),
              labelStyle: TextStyle(
                color: selected ? Colors.white : brandNavy,
                fontSize: 12,
                fontWeight: FontWeight.w900,
              ),
            );
          }).toList(),
        ),
      ],
    );
  }
}

