class _BncProductImagePreview extends StatefulWidget {
  const _BncProductImagePreview({
    required this.title,
    required this.photos,
    required this.initialIndex,
  });

  final String title;
  final List<String> photos;
  final int initialIndex;

  @override
  State<_BncProductImagePreview> createState() =>
      _BncProductImagePreviewState();
}

class _BncProductImagePreviewState extends State<_BncProductImagePreview> {
  late final PageController _controller;
  late int _index;

  @override
  void initState() {
    super.initState();
    _index = widget.initialIndex;
    _controller = PageController(initialPage: widget.initialIndex);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Dialog(
      insetPadding: EdgeInsets.zero,
      backgroundColor: Colors.black,
      child: SizedBox.expand(
        child: SafeArea(
          child: Stack(
            children: [
              PageView.builder(
                controller: _controller,
                itemCount: widget.photos.length,
                onPageChanged: (value) => setState(() => _index = value),
                itemBuilder: (context, index) {
                  return InteractiveViewer(
                    minScale: 1,
                    maxScale: 4,
                    child: Center(
                      child: Image.asset(
                        widget.photos[index],
                        fit: BoxFit.contain,
                        errorBuilder: (_, __, ___) => const Icon(
                          Icons.photo_camera_outlined,
                          color: Colors.white,
                          size: 72,
                        ),
                      ),
                    ),
                  );
                },
              ),
              Positioned(
                left: 16,
                top: 12,
                right: 68,
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      widget.title,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: Colors.white,
                        fontSize: 20,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      '${_index + 1} / ${widget.photos.length}',
                      style: TextStyle(
                        color: Colors.white.withValues(alpha: 0.74),
                        fontSize: 13,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                  ],
                ),
              ),
              Positioned(
                right: 14,
                top: 10,
                child: IconButton(
                  color: Colors.white,
                  onPressed: () => Navigator.of(context).pop(),
                  icon: const Icon(Icons.close_rounded),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _BncProductDetailsPanel extends StatelessWidget {
  const _BncProductDetailsPanel({
    required this.product,
    required this.quantity,
    required this.unit,
  });

  final _BncProductSaleSpec product;
  final int quantity;
  final String unit;

  @override
  Widget build(BuildContext context) {
    final productType = _productTypeLabel(product.name);
    final key = _normalizeKey(product.name);
    final isFashionProduct = _isFashionProductKey(key);
    final usesFashionSizes = _usesFashionSizeOptions(key);
    final isAccessoryProduct = _isAccessoryProductKey(key);
    final quantityText = '$quantity $unit';
    final highlights = usesFashionSizes
        ? [
            ('Brand', _fashionBrandLabel(product.name)),
            ('Type', productType),
            ('Selected Size', unit),
            ('Fit', _fashionFitLabel(product.name)),
            ('Fabric', _fashionFabricLabel(product.name)),
            ('Care', 'Machine wash'),
          ]
        : isFashionProduct
        ? [
            ('Brand', _fashionBrandLabel(product.name)),
            ('Type', productType),
            ('Material', _fashionFabricLabel(product.name)),
            ('Style', 'Ready stock'),
            ('Care', 'Keep dry'),
            ('Warranty', 'Shop warranty'),
          ]
        : isAccessoryProduct
        ? [
            ('Brand', 'BNC Accessories'),
            ('Type', productType),
            ('Style', unit),
            ('Material', _accessoryMaterialLabel(product.name)),
            ('Packaging', 'Box pack'),
            ('Warranty', 'Shop warranty'),
          ]
        : [
            ('Brand', 'Local shop'),
            ('Type', productType),
            ('Organic', _organicLabel(product.name)),
            ('Quantity', quantityText),
            ('Form Factor', _formFactorLabel(product.name)),
            ('Shelf Life', _shelfLifeLabel(product.name)),
            ('Is Perishable', 'Yes'),
            ('Food Type', 'Fresh'),
          ];
    final details = usesFashionSizes
        ? [
            ...highlights,
            ('Origin', 'Kozhikode'),
            ('Packaging', _packagingLabel(product.name)),
            (
              'Available Sizes',
              _unitOptionsForProductName(product.name).join(', '),
            ),
            ('Offer', product.discount),
          ]
        : isFashionProduct
        ? [
            ...highlights,
            ('Origin', 'Kozhikode'),
            ('Packaging', _packagingLabel(product.name)),
            ('Available Styles', _variantsForProductName(product.name)),
            ('Offer', product.discount),
          ]
        : isAccessoryProduct
        ? [
            ...highlights,
            ('Origin', 'Kozhikode'),
            (
              'Available Options',
              _unitOptionsForProductName(product.name).join(', '),
            ),
            ('Offer', product.discount),
          ]
        : [
            ...highlights,
            ('Origin', 'Kozhikode'),
            ('Packaging', _packagingLabel(product.name)),
            ('Net Quantity', quantityText),
            ('Offer', product.discount),
          ];

    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: const Color(0xFFF8FAFF),
        borderRadius: BorderRadius.circular(22),
        border: Border.all(color: brandLine),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const _BncProductDetailHeader(title: 'Product highlights'),
          const SizedBox(height: 12),
          _BncProductSpecGrid(items: highlights),
          const SizedBox(height: 18),
          const _BncProductDetailHeader(title: 'Product details'),
          const SizedBox(height: 12),
          Wrap(
            spacing: 8,
            children: const [
              _BncProductTab(label: 'Specifications', selected: true),
              _BncProductTab(label: 'Shop info'),
            ],
          ),
          const SizedBox(height: 12),
          _BncProductSpecGrid(items: details),
        ],
      ),
    );
  }
}

