String _discountForProductName(String product) {
  final key = _normalizeKey(product);
  if (key.contains('sweetpotato') ||
      key.contains('beetroot') ||
      key.contains('cucumber') ||
      key.contains('okra') ||
      key.contains('ladyfinger') ||
      key.contains('cauliflower')) {
    return '10% OFF';
  }
  if (key.contains('broccoli') ||
      key.contains('sweetcorn') ||
      _isGingerProductKey(key) ||
      _isGarlicProductKey(key)) {
    return '12% OFF';
  }
  if (_isRestaurantFoodProductKey(key)) return 'HOT';
  if (_isAccessoryProductKey(key)) return 'OFFER';
  if (_isFashionProductKey(key)) return 'OFFER';
  if (key.contains('capsicum') || key.contains('peas')) return '8% OFF';
  if (key.contains('tomato')) return '15% OFF';
  if (key.contains('potato') || key.contains('onion')) return '10% OFF';
  if (key.contains('carrot') ||
      key.contains('cabbage') ||
      key.contains('greenbeans')) {
    return '8% OFF';
  }
  if (key.contains('dry') || key.contains('fish') || key.contains('mutton')) {
    return '49%';
  }
  if (key.contains('chicken') ||
      key.contains('beef') ||
      key.contains('combo')) {
    return '38%';
  }
  if (key.contains('leafy') ||
      key.contains('spinach') ||
      key.contains('coriander') ||
      key.contains('mint') ||
      key.contains('moringa') ||
      key.contains('curry') ||
      key.contains('lettuce') ||
      key.contains('amaranth') ||
      key.contains('fenugreek')) {
    return '25%';
  }
  if (key.contains('apple') ||
      key.contains('banana') ||
      key.contains('fruit')) {
    return '30%';
  }
  return '20%';
}

