String _variantsForProductName(String product) {
  final key = _normalizeKey(product);
  if (_usesFreeSizeFashionOption(key)) return 'Free size';
  if (_usesFashionSizeOptions(key)) return '5 sizes';
  if (_isFashionProductKey(key)) return '4 styles';
  if (_isRestaurantFoodProductKey(key)) {
    if (key.contains('family') || key.contains('platter')) return 'Family pack';
    if (key.contains('alfahamquarter')) return 'Quarter';
    if (key.contains('alfahamhalf')) return 'Half';
    if (key.contains('pizza')) return 'Medium';
    if (key.contains('juice')) return '1 glass';
    if (key.contains('snack') ||
        key.contains('cutlet') ||
        key.contains('samosa') ||
        key.contains('bananafry') ||
        key.contains('fries')) {
      return '1 plate';
    }
    return '1 plate';
  }
  if (_isAccessoryProductKey(key)) return '4 styles';
  if (key.contains('rice') ||
      key.contains('dal') ||
      key.contains('gram') ||
      key.contains('chana') ||
      key.contains('rajma')) {
    return '1 kg';
  }
  if (key.contains('tomato') ||
      key.contains('sweetpotato') ||
      key.contains('potato') ||
      key.contains('onion') ||
      key.contains('carrot') ||
      key.contains('beetroot') ||
      key.contains('radish') ||
      key.contains('turnip') ||
      _isGingerProductKey(key) ||
      _isGarlicProductKey(key) ||
      key.contains('cucumber') ||
      key.contains('greenchili') ||
      key.contains('greenchilie') ||
      key.contains('capsicum') ||
      key.contains('okra') ||
      key.contains('ladyfinger') ||
      key.contains('peas') ||
      key.contains('bittergourd') ||
      key.contains('bottlegourd') ||
      key.contains('cauliflower') ||
      key.contains('broccoli') ||
      key.contains('pumpkin') ||
      key.contains('sweetcorn') ||
      key.contains('mushroom') ||
      key.contains('cabbage')) {
    return '1 kg';
  }
  if (key.contains('spinach') ||
      key.contains('coriander') ||
      key.contains('mint') ||
      key.contains('moringa') ||
      key.contains('curry') ||
      key.contains('lettuce') ||
      key.contains('amaranth') ||
      key.contains('fenugreek') ||
      key.contains('leafy')) {
    return '1 bunch';
  }
  if (key.contains('dry')) return '4 variants';
  if (key.contains('fish') || key.contains('meat') || key.contains('chicken')) {
    return '3 packs';
  }
  if (key.contains('fruit')) return '5 options';
  return '2 sizes';
}

bool _showsDetailedSubcategoryList(
  String categoryName,
  String subcategoryName,
) {
  final categoryKey = _normalizeKey(categoryName);
  final key = _normalizeKey(subcategoryName);
  if (_isRestaurantTopLevelKey(categoryKey) ||
      _isRestaurantTopLevelKey(key) ||
      _isRestaurantFoodGroupKey(key) ||
      _isRestaurantFoodProductKey(key)) {
    return false;
  }

  if (categoryKey.contains('grocery') ||
      categoryKey.contains('mobile') ||
      categoryKey.contains('food') ||
      categoryKey.contains('bakery') ||
      categoryKey.contains('fashion') ||
      categoryKey.contains('footwear')) {
    return true;
  }

  return key == 'rice' ||
      key.contains('dal') ||
      key.contains('pulse') ||
      key.contains('oil') ||
      key.contains('flour') ||
      key.contains('atta') ||
      key.contains('sugar') ||
