      key.contains('cookie') ||
      key.contains('salt') ||
      key.contains('cleaning') ||
      key.contains('detergent') ||
      key.contains('fish') ||
      key.contains('fruit') ||
      key.contains('meat') ||
      key.contains('gift') ||
      key.contains('care') ||
      key.contains('repair') ||
      key.contains('kurti') ||
      key.contains('saree') ||
      key.contains('jewellery') ||
      key.contains('jewelry') ||
      key.contains('partywear') ||
      key.contains('bag') ||
      key.contains('footwear') ||
      key.contains('shoe') ||
      key.contains('sandal') ||
      key.contains('sneaker') ||
      key.contains('kidswear') ||
      key.contains('schoolwear') ||
      key.contains('babyitem') ||
      key.contains('accessor');
