String _subcategoryListTitle(String categoryName, String subcategoryName) {
  final categoryKey = _normalizeKey(categoryName);
  final key = _normalizeKey(subcategoryName);
  if (key == 'rice') return 'Rice varieties with price';
  if (key.contains('dal') || key.contains('pulse')) {
    return 'Dals and pulses with price';
  }
  if (key.contains('oil')) return 'Cooking oils with price';
  if (key.contains('flour') || key.contains('atta')) {
    return 'Flour and atta with price';
  }
  if (key.contains('spice') || key.contains('masala')) {
    return 'Spices and masala with price';
  }
  if (key.contains('fish') || categoryKey.contains('fish')) {
    return 'Fish options with price';
  }
  if (key.contains('meal') || categoryKey.contains('keralameals')) {
    return 'Meal options with price';
  }
  if (key.contains('fruit') || categoryKey.contains('fruit')) {
    return 'Fruit options with price';
  }
  if (key.contains('gift') || categoryKey.contains('gift')) {
    return 'Gift pack options with price';
  }
  if (categoryKey.contains('accessor') ||
      _isAccessoryTopLevelKey(categoryKey)) {
    return 'Accessory items with price';
  }
  if (categoryKey.contains('restaurant') ||
      categoryKey.contains('hotel') ||
      categoryKey.contains('food') ||
      _isRestaurantTopLevelKey(categoryKey)) {
    return 'Food items with price';
  }
  if (key.contains('shirt') ||
      key.contains('pant') ||
      key.contains('trouser') ||
      key.contains('ethnic') ||
      key.contains('formal') ||
      key.contains('kurti') ||
      key.contains('saree') ||
      key.contains('jewellery') ||
      key.contains('jewelry') ||
      key.contains('party') ||
      key.contains('bag') ||
      key.contains('shoe') ||
      key.contains('footwear') ||
      key.contains('kids') ||
      categoryKey.contains('fashion') ||
      categoryKey.contains('footwear')) {
    return 'Fashion items with size options';
  }
  if (key.contains('care') || categoryKey.contains('personalcare')) {
    return 'Personal care options with price';
  }
  if (key.contains('accessor') || categoryKey.contains('mobile')) {
    return '$subcategoryName options with price';
  }
  return '$subcategoryName options with price';
}

bool _isFreshHerbProductKey(String key) {
  return key.contains('leafy') ||
      key.contains('spinach') ||
      (key.contains('coriander') && !key.contains('powder')) ||
      key == 'mint' ||
      key == 'mintleaves' ||
      key.contains('moringa') ||
      key == 'curryleaves' ||
      key == 'curryleaf' ||
      key.contains('lettuce') ||
      key.contains('amaranth') ||
      key.contains('fenugreek');
}

bool _isSpiceProductKey(String key, String subcategoryKey) {
  return subcategoryKey.contains('spice') ||
      subcategoryKey.contains('masala') ||
      key.contains('spice') ||
      key.contains('masala') ||
      key.contains('powder') ||
      key.contains('turmeric') ||
      key.contains('chilli') ||
      key.contains('pepper') ||
      key.contains('cumin') ||
      key.contains('mustardseeds') ||
      key.contains('cardamom');
}

