String _fashionBrandLabel(String product) {
  final key = _normalizeKey(product);
  if (key.contains('saree')) return 'Kerala Saree House';
  if (key.contains('kurti')) return 'Urban Kurti';
  if (key.contains('jewellery') ||
      key.contains('jewelry') ||
      key.contains('necklace') ||
      key.contains('earring') ||
      key.contains('bangle')) {
    return 'Star Jewels';
  }
  if (key.contains('bag') || key.contains('wallet')) return 'Carry Studio';
  if (key.contains('shoe') ||
      key.contains('sandal') ||
      key.contains('sneaker') ||
      key.contains('heel') ||
      key.contains('flat') ||
      key.contains('footwear')) {
    return 'Step Fit';
  }
  if (key.contains('kids') || key.contains('baby')) return 'Little BNC';
  if (key.contains('urban')) return 'Urban Classic';
  if (key.contains('denim')) return 'Denim Co';
  if (key.contains('linen')) return 'Linen House';
  if (key.contains('premium')) return 'Premium Fit';
  if (key.contains('classic')) return 'Classic Wear';
  if (key.contains('office')) return 'Office Fit';
  if (key.contains('kurta')) return 'Kerala Ethnic';
  return 'BNC Fashion';
}

String _fashionFitLabel(String product) {
  final key = _normalizeKey(product);
  if (key.contains('slim')) return 'Slim fit';
  if (key.contains('saree')) return 'Free drape';
  if (key.contains('shoe') ||
      key.contains('sandal') ||
      key.contains('sneaker') ||
      key.contains('heel') ||
      key.contains('flat')) {
    return 'Regular fit';
  }
  if (key.contains('formal') || key.contains('office')) return 'Regular fit';
  if (key.contains('ethnic') ||
      key.contains('kurta') ||
      key.contains('kurti') ||
      key.contains('kids') ||
      key.contains('baby')) {
    return 'Comfort fit';
  }
  return 'Regular fit';
}

String _fashionFabricLabel(String product) {
  final key = _normalizeKey(product);
  if (key.contains('saree')) return 'Silk cotton';
  if (key.contains('kurti')) return 'Rayon cotton';
  if (key.contains('jewellery') ||
      key.contains('jewelry') ||
      key.contains('necklace') ||
      key.contains('earring') ||
      key.contains('bangle')) {
    return 'Gold plated';
  }
  if (key.contains('bag') || key.contains('wallet')) return 'Vegan leather';
  if (key.contains('shoe') ||
      key.contains('sandal') ||
      key.contains('sneaker') ||
      key.contains('heel') ||
      key.contains('flat')) {
    return 'Cushioned sole';
  }
  if (key.contains('kids') || key.contains('baby')) return 'Soft cotton';
  if (key.contains('linen')) return 'Linen blend';
  if (key.contains('denim')) return 'Cotton denim';
  if (key.contains('pant') || key.contains('trouser')) return 'Cotton twill';
  if (key.contains('ethnic') || key.contains('kurta')) return 'Cotton silk';
  return 'Cotton blend';
}

String _accessoryMaterialLabel(String product) {
  final key = _normalizeKey(product);
  if (key.contains('watch')) return 'Stainless steel';
  if (key.contains('sunglass')) return 'UV lens';
  if (key.contains('glass') || key.contains('frame') || key.contains('lens')) {
    return 'Optical frame';
  }
  if (key.contains('chain') || key.contains('bracelet')) return 'Plated metal';
  return 'Mixed material';
}

List<(String, String)> _apparelSizeChartRows(String product) {
  final key = _normalizeKey(product);
  if (key.contains('shoe') ||
      key.contains('sandal') ||
      key.contains('sneaker') ||
      key.contains('heel') ||
      key.contains('flat') ||
      key.contains('footwear')) {
    return const [
      ('6', 'Foot length 24.5 cm'),
      ('7', 'Foot length 25.2 cm'),
      ('8', 'Foot length 26.0 cm'),
      ('9', 'Foot length 26.7 cm'),
      ('10', 'Foot length 27.5 cm'),
    ];
  }
  if (key.contains('pant') || key.contains('trouser')) {
    return const [
      ('28', 'Waist 28 in / Hip 36 in'),
      ('30', 'Waist 30 in / Hip 38 in'),
      ('32', 'Waist 32 in / Hip 40 in'),
      ('34', 'Waist 34 in / Hip 42 in'),
      ('36', 'Waist 36 in / Hip 44 in'),
    ];
  }
  return const [
    ('S', 'Chest 38 in / Shoulder 17 in'),
    ('M', 'Chest 40 in / Shoulder 18 in'),
    ('L', 'Chest 42 in / Shoulder 19 in'),
    ('XL', 'Chest 44 in / Shoulder 20 in'),
    ('XXL', 'Chest 46 in / Shoulder 21 in'),
  ];
}

