List<String> _unitOptionsForProductName(String product) {
  final key = _normalizeKey(product);
  if (_usesFreeSizeFashionOption(key)) {
    return const ['Free size'];
  }
  if (_usesFashionSizeOptions(key)) {
    if (key.contains('shoe') ||
        key.contains('sandal') ||
        key.contains('sneaker') ||
        key.contains('heel') ||
        key.contains('flat') ||
        key.contains('footwear')) {
      return const ['6', '7', '8', '9', '10'];
    }
    if (key.contains('jeans') ||
        key.contains('pant') ||
        key.contains('trouser')) {
      return const ['28', '30', '32', '34', '36'];
    }
    return const ['S', 'M', 'L', 'XL', 'XXL'];
  }
  if (_isRestaurantFoodProductKey(key)) {
    if (key.contains('alfaham')) {
      return const ['Quarter', 'Half', 'Full'];
    }
    if (key.contains('pizza')) {
      return const ['Small', 'Medium', 'Large'];
    }
    if (key.contains('family') || key.contains('platter')) {
      return const ['Family pack', 'Party pack'];
    }
    if (key.contains('juice')) {
      return const ['1 glass', '2 glasses'];
    }
    return const ['1 plate', '2 plates', 'Family pack'];
  }
  if (_isAccessoryProductKey(key)) {
    if (key.contains('watch')) {
      return const ['Black', 'Silver', 'Brown', 'Blue'];
    }
    if (key.contains('sunglass') ||
        key.contains('glass') ||
        key.contains('frame') ||
        key.contains('lens')) {
      return const ['Black', 'Brown', 'Clear', 'Blue cut'];
    }
    if (key.contains('chain') || key.contains('bracelet')) {
      return const ['Gold', 'Silver', 'Rose gold', 'Black'];
    }
    return const ['Classic', 'Premium', 'Daily', 'Gift'];
  }
  if (_isFreshHerbProductKey(key)) {
    return const ['1 bunch', '2 bunches', '500 g'];
  }
  if (_isGingerProductKey(key) ||
      _isGarlicProductKey(key) ||
      key.contains('greenchili') ||
      key.contains('greenchilie')) {
    return const ['250 g', '500 g', '1 kg'];
  }
  if (key.contains('corn')) {
    return const ['2 pcs', '4 pcs', '1 kg'];
  }
  return const ['500 g', '1 kg', '2 kg', '3 kg', '5 kg', '10 kg'];
}

String _priceForSelectedUnit(
  String basePrice,
  String baseUnit,
  String selectedUnit,
) {
  final amount = int.tryParse(basePrice.replaceAll(RegExp(r'[^0-9]'), ''));
  if (amount == null) {
    return basePrice;
  }

  final base = _unitValue(baseUnit);
  final selected = _unitValue(selectedUnit);
  if (base <= 0 || selected <= 0) {
    return basePrice;
  }

  return 'Rs${(amount * selected / base).round()}';
}

String _priceForQuantity(String price, int quantity) {
  final amount = int.tryParse(price.replaceAll(RegExp(r'[^0-9]'), ''));
  if (amount == null) {
    return price;
  }
  return 'Rs${amount * quantity}';
}

bool _usesProductWeightControls(String categoryName) {
  final key = _normalizeKey(categoryName);
  return key.contains('grocery');
}

String _productTypeLabel(String product) {
  final key = _normalizeKey(product);
  if (_isAccessoryProductKey(key)) {
    if (key.contains('watch')) return 'Watch';
    if (key.contains('sunglass')) return 'Sunglasses';
    if (key.contains('glass') ||
        key.contains('frame') ||
        key.contains('lens')) {
      return 'Spectacles';
    }
    if (key.contains('chain')) return 'Chain';
    if (key.contains('bracelet')) return 'Bracelet';
    return 'Accessory';
  }
  if (_isRestaurantFoodProductKey(key)) {
    if (key.contains('alfaham') || key.contains('grilled')) return 'Grill';
    if (key.contains('biryani')) return 'Biryani';
    if (key.contains('meal') || key.contains('sadya')) return 'Meals';
    if (key.contains('pizza') || key.contains('burger')) return 'Fast food';
    if (key.contains('fish') ||
        key.contains('seafood') ||
        key.contains('prawns')) {
      return 'Seafood';
    }
    if (key.contains('snack') ||
        key.contains('cutlet') ||
        key.contains('samosa')) {
      return 'Snacks';
    }
    return 'Restaurant item';
  }
  if (_isFashionProductKey(key)) {
    if (key.contains('ladiesjeans') || key.contains('womenjeans')) {
      return 'Ladies jeans';
    }
    if (key.contains('jeans')) return 'Men jeans';
    if (key.contains('tshirt')) return 'Men T-shirt';
    if (key.contains('saree')) return 'Women saree';
    if (key.contains('ladiestop') || key.contains('womentop')) {
      return 'Women top';
    }
    if (key.contains('legging')) return 'Women leggings';
    if (key.contains('gown')) return 'Women gown';
    if (key.contains('kurti')) return 'Women kurti';
    if (key.contains('jewellery') ||
        key.contains('jewelry') ||
        key.contains('necklace') ||
        key.contains('earring') ||
        key.contains('bangle')) {
      return 'Jewellery';
    }
    if (key.contains('bag') || key.contains('wallet')) return 'Bag';
    if (key.contains('shoe') ||
        key.contains('sandal') ||
        key.contains('sneaker') ||
        key.contains('heel') ||
        key.contains('flat') ||
        key.contains('footwear')) {
      return 'Footwear';
    }
    if (key.contains('kids') || key.contains('baby')) return 'Kids wear';
    if (key.contains('party')) return 'Party wear';
    if (key.contains('pant') || key.contains('trouser')) return 'Men pants';
    if (key.contains('ethnic') || key.contains('kurta')) return 'Ethnic wear';
    if (key.contains('formal')) return 'Formal wear';
    return 'Men shirt';
  }
  if (key.contains('tomato')) return 'Tomato Local';
  if (key.contains('potato')) return 'Potato';
  if (key.contains('onion')) return 'Red Onion';
  if (key.contains('carrot')) return 'Carrot';
  if (_isFreshHerbProductKey(key)) {
    return 'Leafy greens';
  }
  if (key.contains('fish')) return 'Fresh fish';
  if (key.contains('chicken')) return 'Chicken';
  if (key.contains('mutton')) return 'Mutton';
  return product;
}

String _organicLabel(String product) {
  final key = _normalizeKey(product);
  if (_isRestaurantFoodProductKey(key)) return 'No';
  return key.contains('organic') ? 'Yes' : 'No';
}

String _formFactorLabel(String product) {
  final key = _normalizeKey(product);
  if (_isAccessoryProductKey(key)) return 'Ready style';
  if (_isRestaurantFoodProductKey(key)) return 'Ready to eat';
  if (_isFashionProductKey(key)) return 'Ready size';
  if (key.contains('cut') || key.contains('packs')) return 'Packed';
  if (_isFreshHerbProductKey(key)) return 'Bunch';
  return 'Whole';
}

String _shelfLifeLabel(String product) {
  final key = _normalizeKey(product);
  if (_isAccessoryProductKey(key)) return 'Shop warranty';
  if (_isRestaurantFoodProductKey(key)) return 'Serve hot';
  if (_isFashionProductKey(key)) return 'Wash care';
  if (key.contains('fish') || key.contains('meat') || key.contains('chicken')) {
    return '1 Day';
  }
  if (_isFreshHerbProductKey(key)) return '2 Days';
  return '7 Days';
}

String _packagingLabel(String product) {
  final key = _normalizeKey(product);
  if (_isAccessoryProductKey(key)) return 'Box pack';
  if (_isRestaurantFoodProductKey(key)) return 'Dine-in / parcel';
  if (_isFashionProductKey(key)) return 'Brand pack';
  if (_isFreshHerbProductKey(key)) return 'Fresh bundle';
  if (key.contains('fish') || key.contains('meat') || key.contains('chicken')) {
    return 'Sealed pack';
  }
  return 'Perforated cover';
}

double _unitValue(String unit) {
  final key = unit.toLowerCase().replaceAll(' ', '');
  if (key.contains('250g')) return 0.25;
  if (key.contains('500g')) return 0.5;
  if (key.contains('1kg')) return 1;
  if (key.contains('2kg')) return 2;
  if (key.contains('3kg')) return 3;
  if (key.contains('5kg')) return 5;
  if (key.contains('10kg')) return 10;
  if (key.contains('1bunch')) return 1;
  if (key.contains('2bunch')) return 2;
  if (key.contains('2pcs')) return 1;
  if (key.contains('4pcs')) return 2;
  if (key.contains('quarter')) return 1;
  if (key.contains('half')) return 1.8;
  if (key.contains('full')) return 3.4;
  if (key.contains('small')) return 0.75;
  if (key.contains('medium')) return 1;
  if (key.contains('large')) return 1.45;
  if (key.contains('1plate')) return 1;
  if (key.contains('2plate')) return 2;
  if (key.contains('1glass')) return 1;
  if (key.contains('2glass')) return 2;
  if (key.contains('familypack')) return 3;
  if (key.contains('partypack')) return 5;
  return 1;
}

Future<void> _shareProductDetails(
  BuildContext context, {
  required _BncProductSaleSpec product,
  required _BncShopSpec shop,
  required String unit,
  required String price,
  required String oldPrice,
}) async {
  final message = [
    '${product.name} at ${shop.name}',
    'Unit: $unit',
    'Offer price: $price',
    'Old price: $oldPrice',
    'Discount: ${product.discount}',
    'Location: ${_shopAreaLabel(shop)}, ${shop.distance}',
    'Available on BNC.',
  ].join('\n');

  await Clipboard.setData(ClipboardData(text: message));
  if (!context.mounted) return;
  ScaffoldMessenger.of(context).showSnackBar(
    const SnackBar(
      content: Text(
        'Product details copied. Share it on WhatsApp or social apps.',
      ),
      behavior: SnackBarBehavior.floating,
    ),
  );
}

String _badgeForProductName(String product) {
  final key = _normalizeKey(product);
  if (_usesFreeSizeFashionOption(key)) return 'Free size';
  if (_usesFashionSizeOptions(key)) return 'Size chart';
  if (_isFashionProductKey(key)) return '4 styles';
  if (_isRestaurantFoodProductKey(key)) return _variantsForProductName(product);
  if (_isAccessoryProductKey(key)) return '4 styles';
  if (key.contains('tomato') ||
      key.contains('sweetpotato') ||
      key.contains('potato') ||
      key.contains('onion') ||
      key.contains('carrot') ||
      key.contains('beetroot') ||
      key.contains('radish') ||
      key.contains('turnip') ||
      _isGingerProductKey(key) ||
      _isGarlicProductKey(key) ||
      key.contains('cucumber') ||
      key.contains('greenchili') ||
      key.contains('greenchilie') ||
      key.contains('capsicum') ||
      key.contains('okra') ||
      key.contains('ladyfinger') ||
      key.contains('peas') ||
      key.contains('bittergourd') ||
      key.contains('bottlegourd') ||
      key.contains('cauliflower') ||
      key.contains('broccoli') ||
      key.contains('pumpkin') ||
      key.contains('sweetcorn') ||
      key.contains('mushroom') ||
      key.contains('cabbage') ||
      key.contains('greenbeans') ||
      _isFreshHerbProductKey(key)) {
    return 'Fresh';
  }
  return 'Hot Deal';
}

String _shopAreaLabel(_BncShopSpec shop) {
  final area = shop.address?.area ?? '';
  if (area.isNotEmpty) {
    return area;
  }
  return shop.category;
}

