class _SubcategoryVisual {
  const _SubcategoryVisual({
    required this.label,
    required this.icon,
    required this.colors,
  });

  final String label;
  final IconData icon;
  final List<Color> colors;
}

String _subcategoryRealImageFor(
  String tag,
  String categoryName,
  String fallbackAsset,
) {
  final key = tag.toLowerCase();
  final categoryKey = categoryName.toLowerCase();
  final isBakery =
      categoryKey.contains('bakery') ||
      categoryKey.contains('sweets') ||
      key.contains('cake');

  if (isBakery && key.contains('birthday')) {
    return '$_mockupPath/subcategory/sc-birthday-cake-real.jpg';
  }
  if (isBakery && key.contains('cream')) {
    return '$_mockupPath/subcategory/sc-cream-cake-real.jpg';
  }
  if (isBakery && key.contains('photo')) {
    return '$_mockupPath/subcategory/sc-photo-cake-real.jpg';
  }
  if (isBakery && key.contains('wedding')) {
    return '$_mockupPath/subcategory/sc-wedding-cake-real.jpg';
  }
  if (isBakery && key.contains('custom')) {
    return '$_mockupPath/subcategory/sc-custom-cake-real.jpg';
  }
  if (categoryKey.contains('fashion') ||
      categoryKey.contains('footwear') ||
      key.contains('kurti') ||
      key.contains('saree') ||
      key.contains('jewellery') ||
      key.contains('jewelry') ||
      key.contains('party wear') ||
      key.contains('partywear') ||
      key.contains('bag') ||
      key.contains('accessor') ||
      key.contains('footwear') ||
      key.contains('shoe') ||
      key.contains('sandal') ||
      key.contains('sneaker') ||
      key.contains('kids wear') ||
      key.contains('kidswear') ||
      key.contains('school wear') ||
      key.contains('schoolwear') ||
      key.contains('baby item') ||
      key.contains('babyitem')) {
    if (key.contains('kurti')) {
      return '$_mockupPath/products/fashion-real-kurti.png';
    }
    if (key.contains('saree')) {
      return '$_mockupPath/products/fashion-real-saree.png';
    }
    if (key.contains('jewellery') || key.contains('jewelry')) {
      return '$_mockupPath/products/fashion-real-jewellery.png';
    }
    if (key.contains('party wear') || key.contains('partywear')) {
      return '$_mockupPath/products/fashion-real-party-wear.png';
    }
    if (key.contains('bag') || key.contains('accessor')) {
      return '$_mockupPath/products/fashion-real-bag.png';
    }
    if (key.contains('footwear') ||
        key.contains('shoe') ||
        key.contains('sandal') ||
        key.contains('sneaker')) {
      return '$_mockupPath/products/fashion-real-shoes.png';
    }
    if (key.contains('kids wear') ||
        key.contains('kidswear') ||
        key.contains('school wear') ||
        key.contains('schoolwear') ||
        key.contains('baby item') ||
        key.contains('babyitem')) {
      return '$_mockupPath/products/fashion-real-kids-wear.png';
    }
    if (key.contains('shirt')) {
      return '$_mockupPath/products/fashion-real-shirt.png';
    }
    if (key.contains('pant') || key.contains('trouser')) {
      return '$_mockupPath/products/fashion-real-pants.png';
    }
    if (key.contains('ethnic')) {
      return '$_mockupPath/products/fashion-real-ethnic-wear.png';
    }
    if (key.contains('formal')) {
      return '$_mockupPath/products/fashion-real-formal-wear.png';
    }
  }
  return _subcategoryImageFor(tag, categoryName, fallbackAsset);
}

